import React, { useState, useEffect } from 'react';
import { ChevronLeft, ChevronRight, Calendar, Info, BookOpen, User, Users, Activity, FileText } from 'lucide-react';

// --- DATA TAKWIM 2026 ---
// Data ini disusun berdasarkan input pengguna untuk SMA Ulu Jempol
const schoolData = {
  terms: [
    { name: "Penggal 1", start: "2026-01-12", end: "2026-03-20" },
    { name: "Cuti Penggal 1", start: "2026-03-21", end: "2026-03-29", isHoliday: true },
    { name: "Penggal 2", start: "2026-03-30", end: "2026-05-22" },
    { name: "Cuti Pertengahan Tahun", start: "2026-05-23", end: "2026-06-07", isHoliday: true },
    { name: "Penggal 3", start: "2026-06-08", end: "2026-08-28" },
    { name: "Cuti Penggal 2", start: "2026-08-29", end: "2026-09-06", isHoliday: true },
    { name: "Penggal 4", start: "2026-09-07", end: "2026-12-04" },
    { name: "Cuti Akhir Persekolahan", start: "2026-12-05", end: "2026-12-31", isHoliday: true },
  ],
  events: [
    // --- JANUARI ---
    { date: "2026-01-10", title: "Mesyuarat Guru/Kurikulum/HEM/Koko Bil 1", category: "meeting" },
    { date: "2026-01-12", title: "Mula Persekolahan Penggal 1", category: "academic" },
    { date: "2026-01-13", title: "Minggu Mawaddah Ting 1 (Mula)", category: "hem" },
    { date: "2026-01-14", title: "Minggu Mawaddah Ting 1", category: "hem" },
    { date: "2026-01-15", title: "Minggu Mawaddah Ting 1 (Tamat) & Latihan Merentas Desa", category: "hem" },
    { date: "2026-01-16", title: "Sambutan Israk Mikraj", category: "program" },
    { date: "2026-01-19", title: "Watikah Pemimpin Murid & Intervensi Dini (Mula)", category: "hem" },
    { date: "2026-01-21", title: "Latihan Merentas Desa & Intervensi Dini (Tamat)", category: "koko" },
    { date: "2026-01-23", title: "Kejohanan Merentas Desa", category: "koko" },
    { date: "2026-01-27", title: "Mesyuarat AJK PIBG Bil 1", category: "meeting" },

    // --- FEBRUARI ---
    { date: "2026-02-02", title: "Pelancaran Sekolah Penyayang", category: "hem" },
    { date: "2026-02-04", title: "Mesyuarat Agung PIBG & Penyerahan BAP", category: "program" },
    { date: "2026-02-05", title: "Sukantara (Hari 1)", category: "koko" },
    { date: "2026-02-06", title: "Sukantara (Hari 2)", category: "koko" },
    { date: "2026-02-08", title: "Sukan Tahunan Sekolah", category: "koko" },
    { date: "2026-02-09", title: "Cuti Peristiwa (Pasca Sukan)", category: "holiday" },
    { date: "2026-02-16", title: "Cuti Tambahan KPM (TBC)", category: "holiday" },
    { date: "2026-02-17", title: "Tahun Baru Cina (Hari 1)", category: "holiday" },
    { date: "2026-02-18", title: "Tahun Baru Cina (Hari 2)", category: "holiday" },
    { date: "2026-02-19", title: "Cuti Tambahan KPM (TBC) & Mula Program Ihya’ Ramadan", category: "holiday" },
    { date: "2026-02-20", title: "Cuti Tambahan KPM (TBC)", category: "holiday" },

    // --- MAC ---
    { date: "2026-03-01", title: "Spot Check (Sepanjang Bulan)", category: "hem" },
    { date: "2026-03-19", title: "Cuti Tambahan KPM (Aidilfitri)", category: "holiday" },
    { date: "2026-03-20", title: "Cuti Tambahan KPM (Aidilfitri)", category: "holiday" },
    { date: "2026-03-21", title: "Hari Raya Aidilfitri (Hari 1)", category: "holiday" },
    { date: "2026-03-22", title: "Hari Raya Aidilfitri (Hari 2)", category: "holiday" },

    // --- APRIL ---
    { date: "2026-04-03", title: "Jamuan Aidilfitri", category: "program" },
    { date: "2026-04-10", title: "Mesyuarat AJK PIBG Bil 2", category: "meeting" },
    { date: "2026-04-11", title: "Bengkel Bahasa SPM (Siri 1)", category: "academic" },
    { date: "2026-04-14", title: "Perkampungan Ilmu Siri 1 (Mula)", category: "academic" },
    { date: "2026-04-17", title: "Perkampungan Ilmu Siri 1 (Tamat)", category: "academic" },
    { date: "2026-04-21", title: "Mesyuarat Guru Bil 2", category: "meeting" },
    { date: "2026-04-27", title: "PPT Ting 4&5 Mula", category: "exam" },

    // --- MEI ---
    { date: "2026-05-04", title: "Minggu Bahasa Arab (Mula)", category: "academic" },
    { date: "2026-05-08", title: "Minggu Bahasa Arab (Tamat)", category: "academic" },
    { date: "2026-05-11", title: "PPT Ting 1-3 Mula", category: "exam" },
    { date: "2026-05-12", title: "Gotong-Royong Perdana", category: "hem" },
    { date: "2026-05-15", title: "Sambutan Hari Guru & PPT Tamat", category: "program" },
    { date: "2026-05-23", title: "Bengkel JUJ Siri 1", category: "academic" },
    // Note: Karnival Gegar Didik, Minggu Sains pada bulan Mei (tarikh umum)

    // --- JUN ---
    { date: "2026-06-01", title: "Spot Check (Sepanjang Bulan)", category: "hem" },
    { date: "2026-06-13", title: "Perkhemahan Perdana KRS (Mula)", category: "koko" },
    { date: "2026-06-14", title: "Perkhemahan Perdana KRS (Tamat)", category: "koko" },
    { date: "2026-06-15", title: "Cuti Peristiwa (Pasca Perkhemahan)", category: "holiday" },
    { date: "2026-06-17", title: "Sambutan Maal Hijrah", category: "program" },
    { date: "2026-06-28", title: "Hari Usahawan", category: "program" },

    // --- JULAI ---
    { date: "2026-07-15", title: "Bengkel Bahasa SPM (Siri 2)", category: "academic" },
    { date: "2026-07-20", title: "Minggu PPDa (Mula)", category: "hem" },
    { date: "2026-07-23", title: "Mesyuarat AJK PIBG Bil 3", category: "meeting" },
    { date: "2026-07-24", title: "Minggu PPDa (Tamat)", category: "hem" },

    // --- OGOS ---
    { date: "2026-08-01", title: "Pelancaran Bulan Kemerdekaan", category: "program" },
    { date: "2026-08-01", title: "Spot Check & Latihan Kebakaran (Bulan ini)", category: "hem" },
    { date: "2026-08-08", title: "Mesyuarat Guru Bil 3 & Gegar Sejarah SPM", category: "meeting" },
    { date: "2026-08-10", title: "Percubaan SPM (Mula)", category: "exam" },
    { date: "2026-08-28", title: "Sambutan Maulidur Rasul", category: "program" },
    { date: "2026-08-29", title: "Percubaan SPM (Tamat)", category: "exam" },

    // --- SEPTEMBER ---
    { date: "2026-09-14", title: "Penutupan Bulan Kemerdekaan", category: "program" },
    { date: "2026-09-15", title: "Program Jom Melancong", category: "program" },

    // --- OKTOBER ---
    { date: "2026-10-01", title: "Spot Check (Sepanjang Bulan)", category: "hem" },
    { date: "2026-10-01", title: "Ujian Bertutur/Mendengar SPM (Bulan ini)", category: "exam" },
    { date: "2026-10-02", title: "Program Munajat & Restu Ilmu / Perkampungan Ilmu Siri 2 (Mula)", category: "program" },
    { date: "2026-10-03", title: "Bengkel JUJ Siri 2", category: "academic" },
    { date: "2026-10-04", title: "Perkampungan Ilmu Siri 2 (Tamat)", category: "academic" },
    { date: "2026-10-10", title: "Hari Sukan Negara", category: "koko" },
    { date: "2026-10-21", title: "Bengkel Bahasa SPM (Siri 3)", category: "academic" },
    { date: "2026-10-30", title: "Mesyuarat AJK PIBG Bil 4", category: "meeting" },

    // --- NOVEMBER ---
    { date: "2026-11-01", title: "Majlis Apresiasi & Hari Kualiti (Bulan ini)", category: "program" },
    { date: "2026-11-01", title: "Ujian Bertulis SPM (Bulan ini)", category: "exam" },
    { date: "2026-11-02", title: "PASA Ting 4 (Mula)", category: "exam" },
    { date: "2026-11-08", title: "Hari Deepavali", category: "holiday" },
    { date: "2026-11-09", title: "Cuti Tambahan KPM (Deepavali)", category: "holiday" },
    { date: "2026-11-10", title: "Cuti Tambahan KPM (Deepavali)", category: "holiday" },
    { date: "2026-11-16", title: "PASA Ting 1-3 (Mula)", category: "exam" },
    { date: "2026-11-20", title: "PASA Ting 1-4 (Tamat)", category: "exam" },
    { date: "2026-11-24", title: "Mesyuarat Guru Bil 4", category: "meeting" },

    // --- DISEMBER ---
    { date: "2026-12-02", title: "Halatuju Lepasan SPM", category: "hem" },
    { date: "2026-12-04", title: "Tamat Persekolahan Sesi 2026", category: "academic" },
    { date: "2026-12-25", title: "Hari Krismas", category: "holiday" },
  ],
  recurring: [
    { day: 1, type: "Kokurikulum", desc: "Perhimpunan Rasmi (Isnin Mg 3, 7:30-8:00)" },
    { day: 3, type: "Sukan", desc: "1M1S/Sukan Permainan (Rabu, 2:00-4:30)" }
  ]
};

// Kategori warna
const categoryStyles = {
  academic: "bg-blue-100 text-blue-800 border-blue-200",
  holiday: "bg-red-100 text-red-800 border-red-200",
  exam: "bg-yellow-100 text-yellow-800 border-yellow-200",
  program: "bg-purple-100 text-purple-800 border-purple-200",
  hem: "bg-green-100 text-green-800 border-green-200",
  koko: "bg-orange-100 text-orange-800 border-orange-200",
  meeting: "bg-gray-100 text-gray-800 border-gray-200",
  default: "bg-white text-gray-800 border-gray-100"
};

const categoryLabels = {
  academic: "Akademik/Sekolah",
  holiday: "Cuti",
  exam: "Peperiksaan",
  program: "Program Sekolah",
  hem: "Hal Ehwal Murid",
  koko: "Kokurikulum",
  meeting: "Mesyuarat"
};

const getCategoryIcon = (cat) => {
  switch(cat) {
    case 'academic': return <BookOpen className="w-4 h-4" />;
    case 'holiday': return <Calendar className="w-4 h-4" />;
    case 'exam': return <FileText className="w-4 h-4" />;
    case 'program': return <Activity className="w-4 h-4" />;
    case 'hem': return <User className="w-4 h-4" />;
    case 'koko': return <Activity className="w-4 h-4" />;
    case 'meeting': return <Users className="w-4 h-4" />;
    default: return <Info className="w-4 h-4" />;
  }
};

export default function App() {
  // Tetapan asal: Gunakan tarikh hari ini tetapi dipetakan ke tahun 2026
  // Ini memastikan pengguna melihat bulan/hari semasa dalam konteks takwim 2026
  const getInitialDate = () => {
    const today = new Date();
    return new Date(2026, today.getMonth(), today.getDate());
  };

  const [currentDate, setCurrentDate] = useState(getInitialDate()); 
  const [selectedDate, setSelectedDate] = useState(getInitialDate());
  const [selectedEvents, setSelectedEvents] = useState([]);
  const [activeTab, setActiveTab] = useState('calendar'); // 'calendar' or 'list'

  // Helper: Get days in month
  const getDaysInMonth = (year, month) => new Date(year, month + 1, 0).getDate();

  // Helper: Get day of week for 1st of month (0 = Sunday)
  const getFirstDayOfMonth = (year, month) => new Date(year, month, 1).getDay();

  // Helper: Format date YYYY-MM-DD
  const formatDate = (date) => date.toISOString().split('T')[0];

  // Helper: Check if date is in a range
  const isDateInRange = (dateStr, startStr, endStr) => {
    return dateStr >= startStr && dateStr <= endStr;
  };

  // Logic to find events for a specific date
  const getEventsForDate = (date) => {
    const dateStr = formatDate(date);
    let events = schoolData.events.filter(e => e.date === dateStr);

    // Add School Term / Holiday Term info
    const term = schoolData.terms.find(t => isDateInRange(dateStr, t.start, t.end));
    if (term) {
      // Don't add term label to every single day to avoid clutter, 
      // but maybe add it if it's the start or end, or if no other event exists
      if (events.length === 0 || term.isHoliday) {
        events.push({
          title: term.name,
          category: term.isHoliday ? 'holiday' : 'academic',
          isTermInfo: true
        });
      }
    }

    // Add recurring weekly events (Koko/Sukan)
    // Only if it's a school day (not a holiday term)
    if (term && !term.isHoliday) {
      const dayOfWeek = date.getDay(); // 0 Sun - 6 Sat

      // Sukan Permainan (Wednesday)
      if (dayOfWeek === 3) {
         events.push({ title: "1M1S / Sukan Permainan (2:00 ptg)", category: "koko", isRecurring: true });
      }

      // Perhimpunan Koko (Isnin minggu ke-3)
      // Simple logic: check if day is Monday (1) and date is between 15 and 21
      if (dayOfWeek === 1 && date.getDate() >= 15 && date.getDate() <= 21) {
         events.push({ title: "Perhimpunan Rasmi Kokurikulum", category: "koko", isRecurring: true });
      }
    }

    return events;
  };

  // Update selected events when date changes
  useEffect(() => {
    const events = getEventsForDate(selectedDate);
    setSelectedEvents(events);
  }, [selectedDate]);

  // Navigate months
  const nextMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));
  };

  const prevMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
  };

  const goToToday = () => {
    const today = new Date();
    // Use 2026 equivalent if real today is not 2026
    const targetYear = 2026;
    setCurrentDate(new Date(targetYear, today.getMonth(), 1));
    setSelectedDate(new Date(targetYear, today.getMonth(), today.getDate()));
  };

  const monthNames = [
    "Januari", "Februari", "Mac", "April", "Mei", "Jun",
    "Julai", "Ogos", "September", "Oktober", "November", "Disember"
  ];

  // Render Calendar Grid
  const renderCalendar = () => {
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const daysInMonth = getDaysInMonth(year, month);
    const firstDay = getFirstDayOfMonth(year, month);
    const days = [];

    // Empty cells for days before start of month
    for (let i = 0; i < firstDay; i++) {
      days.push(<div key={`empty-${i}`} className="h-24 bg-gray-50 border border-gray-100"></div>);
    }

    // Days of month
    for (let d = 1; d <= daysInMonth; d++) {
      const currentDayDate = new Date(year, month, d);
      const dateStr = formatDate(currentDayDate);
      const dayEvents = getEventsForDate(currentDayDate);

      // Determine background color based on highest priority event
      let bgClass = "bg-white";
      let isHoliday = false;

      // Check for holiday term first
      const term = schoolData.terms.find(t => isDateInRange(dateStr, t.start, t.end));
      if (term && term.isHoliday) {
        bgClass = "bg-red-50";
        isHoliday = true;
      }

      // Check for specific events (override term color if it's a specific holiday or exam)
      const specificHoliday = dayEvents.find(e => e.category === 'holiday' && !e.isTermInfo);
      const exam = dayEvents.find(e => e.category === 'exam');

      if (specificHoliday) bgClass = "bg-red-100";
      else if (exam) bgClass = "bg-yellow-50";

      const isSelected = formatDate(selectedDate) === dateStr;

      days.push(
        <div 
          key={d} 
          onClick={() => setSelectedDate(currentDayDate)}
          className={`h-20 sm:h-28 border border-gray-100 p-1 relative cursor-pointer transition-colors duration-200 
            ${bgClass} hover:bg-blue-50 
            ${isSelected ? 'ring-2 ring-blue-600 z-10' : ''}`}
        >
          <div className="flex justify-between items-start">
            <span className={`text-sm font-semibold rounded-full w-6 h-6 flex items-center justify-center 
              ${isSelected ? 'bg-blue-600 text-white' : 'text-gray-700'}`}>
              {d}
            </span>
            {dayEvents.length > 0 && (
              <div className="flex gap-1">
                {dayEvents.some(e=>e.category === 'exam') && <div className="w-2 h-2 rounded-full bg-yellow-500"></div>}
                {dayEvents.some(e=>e.category === 'meeting') && <div className="w-2 h-2 rounded-full bg-gray-500"></div>}
                {dayEvents.some(e=>e.category === 'program') && <div className="w-2 h-2 rounded-full bg-purple-500"></div>}
                {dayEvents.some(e=>e.category === 'koko') && <div className="w-2 h-2 rounded-full bg-orange-500"></div>}
              </div>
            )}
          </div>

          {/* Small text preview for desktop */}
          <div className="hidden sm:block mt-1 space-y-1 overflow-hidden">
            {dayEvents.slice(0, 2).map((evt, idx) => (
              <div key={idx} className={`text-[10px] truncate px-1 rounded ${categoryStyles[evt.category] || categoryStyles.default}`}>
                {evt.title}
              </div>
            ))}
            {dayEvents.length > 2 && (
              <div className="text-[10px] text-gray-500 px-1">+{dayEvents.length - 2} lagi</div>
            )}
          </div>
        </div>
      );
    }

    return days;
  };

  return (
    <div className="min-h-screen bg-gray-100 p-4 font-sans text-slate-800">
      <div className="max-w-7xl mx-auto grid grid-cols-1 lg:grid-cols-3 gap-6">

        {/* LEFT COLUMN: Calendar & Navigation */}
        <div className="lg:col-span-2 space-y-6">
          <div className="bg-white rounded-2xl shadow-sm p-4 border border-gray-200">
            {/* Header */}
            <div className="flex flex-col sm:flex-row justify-between items-center mb-6 gap-4">
              <div>
                <h1 className="text-2xl font-bold text-slate-800">Takwim SMA Ulu Jempol</h1>
                <p className="text-slate-500 text-sm">Sesi Persekolahan 2026</p>
              </div>

              <div className="flex items-center gap-2 bg-gray-100 p-1 rounded-lg">
                <button onClick={prevMonth} className="p-2 hover:bg-white rounded-md shadow-sm transition"><ChevronLeft size={20}/></button>
                <div className="w-40 text-center font-semibold text-lg">{monthNames[currentDate.getMonth()]} {currentDate.getFullYear()}</div>
                <button onClick={nextMonth} className="p-2 hover:bg-white rounded-md shadow-sm transition"><ChevronRight size={20}/></button>
              </div>
            </div>

            {/* Days Header */}
            <div className="grid grid-cols-7 mb-2 text-center text-sm font-medium text-gray-500">
              <div className="text-red-500">Ahd</div>
              <div>Isn</div>
              <div>Sel</div>
              <div>Rab</div>
              <div>Kha</div>
              <div>Jum</div>
              <div className="text-red-500">Sab</div>
            </div>

            {/* Calendar Grid */}
            <div className="grid grid-cols-7 bg-white border border-gray-200 rounded-lg overflow-hidden">
              {renderCalendar()}
            </div>

            <div className="mt-4 flex flex-wrap gap-3 text-xs text-gray-600 justify-center">
               <span className="flex items-center gap-1"><div className="w-3 h-3 bg-red-100 border border-red-200"></div> Cuti</span>
               <span className="flex items-center gap-1"><div className="w-3 h-3 bg-blue-100 border border-blue-200"></div> Sekolah</span>
               <span className="flex items-center gap-1"><div className="w-3 h-3 bg-yellow-100 border border-yellow-200"></div> Peperiksaan</span>
               <span className="flex items-center gap-1"><div className="w-3 h-3 bg-purple-100 border border-purple-200"></div> Program</span>
               <span className="flex items-center gap-1"><div className="w-3 h-3 bg-green-100 border border-green-200"></div> HEM</span>
            </div>
          </div>
        </div>

        {/* RIGHT COLUMN: Details Panel */}
        <div className="space-y-6">

          {/* Selected Date Details */}
          <div className="bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden">
             <div className="bg-slate-800 text-white p-6">
                <h2 className="text-3xl font-bold">{selectedDate.getDate()}</h2>
                <h3 className="text-xl opacity-90">{monthNames[selectedDate.getMonth()]} {selectedDate.getFullYear()}</h3>
                <p className="opacity-75 mt-1">
                  {['Ahad', 'Isnin', 'Selasa', 'Rabu', 'Khamis', 'Jumaat', 'Sabtu'][selectedDate.getDay()]}
                </p>
             </div>

             <div className="p-6">
                <h4 className="font-semibold text-gray-700 mb-4 flex items-center gap-2">
                  <Activity size={18} />
                  Aktiviti Hari Ini
                </h4>

                {selectedEvents.length > 0 ? (
                  <div className="space-y-3">
                    {selectedEvents.map((evt, idx) => (
                      <div key={idx} className={`p-3 rounded-lg border-l-4 text-sm ${categoryStyles[evt.category] || categoryStyles.default} border-l-[color:inherit] bg-opacity-30`}>
                        <div className="flex items-start gap-2">
                          <span className="mt-0.5 opacity-70">{getCategoryIcon(evt.category)}</span>
                          <div>
                            <div className="font-medium">{evt.title}</div>
                            <div className="text-xs opacity-75 mt-1 uppercase tracking-wider">{categoryLabels[evt.category] || "Umum"}</div>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                ) : (
                  <div className="text-center py-8 text-gray-400">
                    <p>Tiada aktiviti khusus direkodkan.</p>
                  </div>
                )}
             </div>
          </div>

          {/* Quick Stats / Legend / Upcoming */}
          <div className="bg-white rounded-2xl shadow-sm p-6 border border-gray-200">
            <h4 className="font-semibold text-gray-800 mb-4">Sorotan Bulan Ini ({monthNames[currentDate.getMonth()]})</h4>
            <div className="space-y-4">
              {/* Filter events for current month to show quick list */}
              {schoolData.events
                .filter(e => {
                  const d = new Date(e.date);
                  return d.getMonth() === currentDate.getMonth() && d.getFullYear() === currentDate.getFullYear();
                })
                .sort((a,b) => new Date(a.date) - new Date(b.date))
                .slice(0, 5) // Show top 5
                .map((evt, i) => (
                  <div key={i} className="flex gap-3 items-start">
                    <div className="bg-gray-100 rounded px-2 py-1 text-center min-w-[3rem]">
                      <div className="text-xs font-bold text-gray-500">{new Date(evt.date).getDate()}</div>
                      <div className="text-[10px] text-gray-400">{monthNames[new Date(evt.date).getMonth()].substring(0,3)}</div>
                    </div>
                    <div>
                      <div className="text-sm font-medium text-gray-800 leading-tight">{evt.title}</div>
                      <div className="text-xs text-gray-500 mt-1">{categoryLabels[evt.category]}</div>
                    </div>
                  </div>
                ))
              }
              {schoolData.events.filter(e => new Date(e.date).getMonth() === currentDate.getMonth()).length === 0 && (
                 <p className="text-sm text-gray-500 italic">Tiada acara utama disenaraikan bulan ini.</p>
              )}
            </div>
          </div>

        </div>
      </div>
