// Setup sheet jika belum wujud atau kosong
function setupSheet() {
  const ss = SpreadsheetApp.openById(SHEET_ID);
  let sheet = ss.getSheetByName(SHEET_NAME);

  if (!sheet) {
    sheet = ss.insertSheet(SHEET_NAME);
    // Header row
    sheet.appendRow(['id', 'date', 'title', 'category']);
    // Format header
    sheet.getRange(1, 1, 1, 4).setFontWeight('bold').setBackground('#f3f4f6');
  }

  return sheet;
}

// Fungsi untuk memasukkan data seed jika sheet kosong (kecuali header)
function populateSeedData(sheet) {
  const dataToInsert = SEED_DATA.map(item => {
    return [Utilities.getUuid(), item.date, item.title, item.category];
  });

  // Masukkan secara pukal (bulk insert) untuk prestasi
  if (dataToInsert.length > 0) {
    // Mula dari baris 2 (selepas header)
    sheet.getRange(2, 1, dataToInsert.length, 4).setValues(dataToInsert);
  }
}

// CREATE / UPDATE / DELETE
function doPost(e) {
  const lock = LockService.getScriptLock();
  lock.tryLock(10000);

  try {
    const sheet = setupSheet();
    const data = JSON.parse(e.postData.contents);
    const action = data.action;

    if (action === 'create') {
      const id = Utilities.getUuid();
      // Format: id, date, title, category
      sheet.appendRow([id, data.date, data.title, data.category]);
      return response({ status: 'success', message: 'Event created', id: id });
    }

    else if (action === 'update') {
      const rows = sheet.getDataRange().getValues();
      const headers = rows.shift(); // remove header

      // Find row index by ID (adjust for header + 0-based index)
      const rowIndex = rows.findIndex(r => r[0] === data.id);

      if (rowIndex === -1) {
        return response({ status: 'error', message: 'ID not found' });
      }

      // Update row (rowIndex + 2 because: +1 for header, +1 for 1-based index)
      const range = sheet.getRange(rowIndex + 2, 1, 1, 4);
      range.setValues([[data.id, data.date, data.title, data.category]]);

      return response({ status: 'success', message: 'Event updated' });
    }

    else if (action === 'delete') {
      const rows = sheet.getDataRange().getValues();
      const headers = rows.shift();
      const rowIndex = rows.findIndex(r => r[0] === data.id);

      if (rowIndex === -1) {
        return response({ status: 'error', message: 'ID not found' });
      }

      sheet.deleteRow(rowIndex + 2);
      return response({ status: 'success', message: 'Event deleted' });
    }

    return response({ status: 'error', message: 'Invalid action' });

  } catch (error) {
    return response({ status: 'error', message: error.toString() });
  } finally {
    lock.releaseLock();
  }
}

// READ
function doGet(e) {
  try {
    const sheet = setupSheet();
    let rows = sheet.getDataRange().getValues();

    // Semak jika hanya header yang wujud (length <= 1)
    // Jika ya, masukkan data seed
    if (rows.length <= 1) {
       populateSeedData(sheet);
       // Ambil semula data selepas insert
       rows = sheet.getDataRange().getValues();
    }

    const headers = rows.shift(); // Remove header row

    // Map rows to objects
    const events = rows.map(row => ({
      id: row[0],
      date: formatDate(row[1]), // Ensure date is string YYYY-MM-DD
      title: row[2],
      category: row[3]
    })).filter(e => e.id && e.date); // Filter empty rows

    return response({ status: 'success', data: events });

  } catch (error) {
    return response({ status: 'error', message: error.toString() });
  }
}

// Helper to standardise JSON response
function response(data) {
  return ContentService
    .createTextOutput(JSON.stringify(data))
    .setMimeType(ContentService.MimeType.JSON);
}

// Helper format date object to YYYY-MM-DD
function formatDate(dateObj) {
  if (!dateObj) return "";
  if (typeof dateObj === 'string') return dateObj.substring(0, 10); // Handle string dates

  try {
    const year = dateObj.getFullYear();
    const month = String(dateObj.getMonth() + 1).padStart(2, '0');
    const day = String(dateObj.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  } catch (e) {
    return String(dateObj);
  }
}

