            <div className="mt-4 flex flex-wrap gap-3 text-xs text-gray-600 justify-center">
               <span className="flex items-center gap-1"><div className="w-3 h-3 bg-red-100 border border-red-200"></div> Cuti</span>
               <span className="flex items-center gap-1"><div className="w-3 h-3 bg-blue-100 border border-blue-200"></div> Sekolah</span>
               <span className="flex items-center gap-1"><div className="w-3 h-3 bg-yellow-100 border border-yellow-200"></div> Peperiksaan</span>
               <span className="flex items-center gap-1"><div className="w-3 h-3 bg-purple-100 border border-purple-200"></div> Program</span>
               <span className="flex items-center gap-1"><div className="w-3 h-3 bg-green-100 border border-green-200"></div> HEM</span>
            </div>
          </div>
        </div>

        {/* RIGHT COLUMN: Details Panel */}
        <div className="space-y-6">

          {/* Selected Date Details */}
          <div className="bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden">
             <div className="bg-slate-800 text-white p-6 relative">
                <h2 className="text-3xl font-bold">{selectedDate.getDate()}</h2>
                <h3 className="text-xl opacity-90">{monthNames[selectedDate.getMonth()]} {selectedDate.getFullYear()}</h3>
                <p className="opacity-75 mt-1">
                  {['Ahad', 'Isnin', 'Selasa', 'Rabu', 'Khamis', 'Jumaat', 'Sabtu'][selectedDate.getDay()]}
                </p>
                <button 
                  onClick={openAddModal}
                  className="absolute right-6 top-6 bg-blue-600 hover:bg-blue-500 text-white p-2 rounded-full shadow-lg transition-transform hover:scale-105 active:scale-95" 
                  title="Tambah Aktiviti"
                >
                   <Plus size={20} />
                </button>
             </div>

             <div className="p-6">
                <h4 className="font-semibold text-gray-700 mb-4 flex items-center gap-2">
                  <Activity size={18} />
                  Aktiviti Hari Ini
                </h4>

                {selectedEvents.length > 0 ? (
                  <div className="space-y-3">
                    {selectedEvents.map((evt, idx) => (
                      <div key={idx} className={`p-3 rounded-lg border-l-4 text-sm ${categoryStyles[evt.category] || categoryStyles.default} border-l-[color:inherit] bg-opacity-30 group relative`}>
                        <div className="flex items-start gap-2 pr-12">
                          <span className="mt-0.5 opacity-70">{getCategoryIcon(evt.category)}</span>
                          <div>
                            <div className="font-medium">{evt.title}</div>

                            {/* Display Date Range if different */}
                            {evt.start && evt.end && evt.start !== evt.end && (
                                <div className="text-[10px] text-gray-600 mt-1 font-mono flex items-center gap-1">
                                    <Calendar size={10} />
                                    {formatEventDateRange(evt)}
                                </div>
                            )}

                            <div className="text-xs opacity-75 mt-1 uppercase tracking-wider">{categoryLabels[evt.category] || "Umum"}</div>
                          </div>
                        </div>

                        {/* Actions for database events only (those with ID) */}
                        {evt.id && (
                          <div className="absolute right-2 top-2 flex gap-1 opacity-100 sm:opacity-0 group-hover:opacity-100 transition-opacity">
                             <button onClick={() => openEditModal(evt)} className="p-1.5 bg-white text-blue-600 rounded shadow hover:bg-gray-50" title="Edit">
                               <Edit size={14} />
                             </button>
                             <button onClick={() => deleteEvent(evt.id!)} className="p-1.5 bg-white text-red-600 rounded shadow hover:bg-gray-50" title="Padam">
                               <Trash2 size={14} />
                             </button>
                          </div>
                        )}
                      </div>
                    ))}
                  </div>
                ) : (
                  <div className="text-center py-8 text-gray-400">
                    <p>Tiada aktiviti khusus direkodkan.</p>
                    <button onClick={openAddModal} className="mt-4 text-blue-600 text-sm font-medium hover:underline">Tambah Aktiviti +</button>
                  </div>
                )}
             </div>
          </div>

          {/* Quick Stats / Legend / Upcoming */}
          <div className="bg-white rounded-2xl shadow-sm p-6 border border-gray-200">
            <h4 className="font-semibold text-gray-800 mb-4">Sorotan Bulan Ini ({monthNames[currentDate.getMonth()]})</h4>
            <div className="space-y-4">
              {/* Filter events for current month to show quick list */}
              {events
                .filter(e => {
                  if (!e.start) return false;
                  const d = new Date(e.start);
                  return d.getMonth() === currentDate.getMonth() && d.getFullYear() === currentDate.getFullYear();
                })
                .sort((a,b) => {
                    if (!a.start || !b.start) return 0;
                    return new Date(a.start).getTime() - new Date(b.start).getTime();
                })
                .slice(0, 5) // Show top 5
                .map((evt, i) => (
                  <div key={i} className="flex gap-3 items-start group">
                    <div className="bg-gray-100 rounded px-2 py-1 text-center min-w-[3rem]">
                      <div className="text-xs font-bold text-gray-500">{evt.start ? new Date(evt.start).getDate() : '-'}</div>
                      <div className="text-[10px] text-gray-400">{evt.start ? monthNames[new Date(evt.start).getMonth()].substring(0,3) : '-'}</div>
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="text-sm font-medium text-gray-800 leading-tight truncate">{evt.title}</div>
                      <div className="text-xs text-gray-500 mt-1 flex gap-2">
                        <span>{categoryLabels[evt.category]}</span>
                        {evt.end && evt.end !== evt.start && <span className="text-gray-400 text-[10px] flex items-center"><ArrowRight size={8} className="mx-0.5"/> {new Date(evt.end).getDate()}</span>}
                      </div>
                    </div>
                  </div>
                ))
              }
              {events.filter(e => e.start && new Date(e.start).getMonth() === currentDate.getMonth()).length === 0 && (
                 <p className="text-sm text-gray-500 italic">Tiada acara utama disenaraikan bulan ini.</p>
              )}
            </div>
          </div>

        </div>
      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { ChevronLeft, ChevronRight, Calendar, Info, BookOpen, User, Users, Activity, FileText, Plus, Edit, Trash2, X, Loader2, ArrowRight } from 'lucide-react';

// --- CONFIGURATION ---
const API_URL = "https://script.google.com/macros/s/AKfycbyxauDNUyzxhHLJtDT9gYD5mj88gJADkPCMPFd3JGIfWk34b_xxEftNsbGT4eoEoxxb/exec";

// --- TYPES ---
interface Term {
  name: string;
  start: string;
  end: string;
  isHoliday?: boolean;
}

interface SchoolEvent {
  id?: string; // ID from database
  start?: string; // Replaces 'date'
  end?: string; 
  title: string;
  category: string;
  isTermInfo?: boolean;
  isRecurring?: boolean;
}

interface RecurringEvent {
  day: number;
  type: string;
  desc: string;
}

interface SchoolData {
  terms: Term[];
  recurring: RecurringEvent[];
}

// --- STATIC DATA (Terms & Recurring) ---
const schoolData: SchoolData = {
  terms: [
    { name: "Penggal 1", start: "2026-01-12", end: "2026-03-20" },
    { name: "Cuti Penggal 1", start: "2026-03-21", end: "2026-03-29", isHoliday: true },
    { name: "Penggal 2", start: "2026-03-30", end: "2026-05-22" },
    { name: "Cuti Pertengahan Tahun", start: "2026-05-23", end: "2026-06-07", isHoliday: true },
    { name: "Penggal 3", start: "2026-06-08", end: "2026-08-28" },
    { name: "Cuti Penggal 2", start: "2026-08-29", end: "2026-09-06", isHoliday: true },
    { name: "Penggal 4", start: "2026-09-07", end: "2026-12-04" },
    { name: "Cuti Akhir Persekolahan", start: "2026-12-05", end: "2026-12-31", isHoliday: true },
  ],
  recurring: [
    { day: 1, type: "Kokurikulum", desc: "Perhimpunan Rasmi (Isnin Mg 3, 7:30-8:00)" },
    { day: 3, type: "Sukan", desc: "1M1S/Sukan Permainan (Rabu, 2:00-4:30)" }
  ]
};

// Kategori warna
const categoryStyles: Record<string, string> = {
  academic: "bg-blue-100 text-blue-800 border-blue-200",
  holiday: "bg-red-100 text-red-800 border-red-200",
  exam: "bg-yellow-100 text-yellow-800 border-yellow-200",
  program: "bg-purple-100 text-purple-800 border-purple-200",
  hem: "bg-green-100 text-green-800 border-green-200",
  koko: "bg-orange-100 text-orange-800 border-orange-200",
  meeting: "bg-gray-100 text-gray-800 border-gray-200",
  default: "bg-white text-gray-800 border-gray-100"
};

const categoryLabels: Record<string, string> = {
  academic: "Akademik/Sekolah",
  holiday: "Cuti",
  exam: "Peperiksaan",
  program: "Program Sekolah",
  hem: "Hal Ehwal Murid",
  koko: "Kokurikulum",
  meeting: "Mesyuarat"
};

const getCategoryIcon = (cat: string) => {
  switch(cat) {
    case 'academic': return <BookOpen className="w-4 h-4" />;
    case 'holiday': return <Calendar className="w-4 h-4" />;
    case 'exam': return <FileText className="w-4 h-4" />;
    case 'program': return <Activity className="w-4 h-4" />;
    case 'hem': return <User className="w-4 h-4" />;
    case 'koko': return <Activity className="w-4 h-4" />;
    case 'meeting': return <Users className="w-4 h-4" />;
    default: return <Info className="w-4 h-4" />;
  }
};

export default function App() {
  const getInitialDate = () => {
    const today = new Date();
    // Default to 2026 for this specific calendar app
    return new Date(2026, today.getMonth(), today.getDate());
  };

  const [currentDate, setCurrentDate] = useState<Date>(getInitialDate()); 
  const [selectedDate, setSelectedDate] = useState<Date>(getInitialDate());
  const [events, setEvents] = useState<SchoolEvent[]>([]); // Dynamic events from DB
  const [loading, setLoading] = useState(true);

  // Modal State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [editingEvent, setEditingEvent] = useState<SchoolEvent | null>(null);
  const [formData, setFormData] = useState({ title: '', category: 'academic', start: '', end: '' });

  // --- API FUNCTIONS ---

  const fetchEvents = async () => {
    setLoading(true);
    try {
      const response = await fetch(API_URL);
      const result = await response.json();
      if (result.status === 'success') {
        setEvents(result.data);
      } else {
        console.error("Failed to fetch:", result.message);
      }
    } catch (error) {
      console.error("Error fetching events:", error);
    } finally {
      setLoading(false);
    }
  };

  const saveEvent = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);

    // Validate end date is not before start date
    if (formData.end && formData.start && formData.end < formData.start) {
        alert("Tarikh tamat tidak boleh sebelum tarikh mula.");
        setIsSubmitting(false);
        return;
    }

    try {
      const action = editingEvent ? 'update' : 'create';
      const payload = {
        action,
        id: editingEvent ? editingEvent.id : undefined,
        title: formData.title,
        category: formData.category,
        start: formData.start,
        end: formData.end || formData.start // If end is empty, assume single day
      };

      await fetch(API_URL, {
        method: 'POST',
        body: JSON.stringify(payload),
      });

      await fetchEvents();
      closeModal();
    } catch (error) {
      console.error("Error saving:", error);
      alert("Ralat menyimpan data. Sila cuba lagi.");
    } finally {
      setIsSubmitting(false);
    }
  };

  const deleteEvent = async (id: string) => {
    if(!confirm("Adakah anda pasti mahu memadam aktiviti ini?")) return;

    setLoading(true); 
    try {
      await fetch(API_URL, {
        method: 'POST',
        body: JSON.stringify({ action: 'delete', id }),
      });
      await fetchEvents();
    } catch (error) {
      console.error("Error deleting:", error);
      alert("Ralat memadam data.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchEvents();
  }, []);

  // --- CALENDAR LOGIC ---

  const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
  const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();
  const formatDate = (date: Date) => date.toISOString().split('T')[0];

  const isDateInRange = (dateStr: string, startStr: string, endStr: string) => {
    return dateStr >= startStr && dateStr <= endStr;
  };

  const getEventsForDate = (date: Date): SchoolEvent[] => {
    const dateStr = formatDate(date);

    // 1. Database Events (Check range overlap)
    let dailyEvents: SchoolEvent[] = events.filter(e => {
        if (!e.start) return false;
        const end = e.end || e.start;
        return dateStr >= e.start && dateStr <= end;
    });

    // 2. School Terms
    const term = schoolData.terms.find(t => isDateInRange(dateStr, t.start, t.end));
    if (term) {
      if (dailyEvents.length === 0 || term.isHoliday) {
        dailyEvents.push({
          title: term.name,
          category: term.isHoliday ? 'holiday' : 'academic',
          isTermInfo: true
        });
      }
    }

    // 3. Recurring Events (Only if term exists and not a holiday)
    if (term && !term.isHoliday) {
      const dayOfWeek = date.getDay();
      if (dayOfWeek === 3) {
         dailyEvents.push({ title: "1M1S / Sukan Permainan (2:00 ptg)", category: "koko", isRecurring: true });
      }
      if (dayOfWeek === 1 && date.getDate() >= 15 && date.getDate() <= 21) {
         dailyEvents.push({ title: "Perhimpunan Rasmi Kokurikulum", category: "koko", isRecurring: true });
      }
    }

    return dailyEvents;
  };

  const [selectedEvents, setSelectedEvents] = useState<SchoolEvent[]>([]);

  useEffect(() => {
    const evts = getEventsForDate(selectedDate);
    setSelectedEvents(evts);
  }, [selectedDate, events]);

  const nextMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));
  const prevMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));

  const monthNames = [
    "Januari", "Februari", "Mac", "April", "Mei", "Jun",
    "Julai", "Ogos", "September", "Oktober", "November", "Disember"
  ];

  // --- MODAL HELPERS ---
  const openAddModal = () => {
    setEditingEvent(null);
    const dateStr = formatDate(selectedDate);
    setFormData({
      title: '',
      category: 'program',
      start: dateStr,
      end: dateStr
    });
    setIsModalOpen(true);
  };

  const openEditModal = (evt: SchoolEvent) => {
    setEditingEvent(evt);
    setFormData({
      title: evt.title,
      category: evt.category,
      start: evt.start || '',
      end: evt.end || evt.start || ''
    });
    setIsModalOpen(true);
  };

  const closeModal = () => {
    setIsModalOpen(false);
    setEditingEvent(null);
  };

  // Helper to display date range cleanly
  const formatEventDateRange = (evt: SchoolEvent) => {
      if (!evt.start) return "";
      const d1 = new Date(evt.start);
      if (!evt.end || evt.start === evt.end) {
          return `${d1.getDate()} ${monthNames[d1.getMonth()]}`;
      }
      const d2 = new Date(evt.end);
      // Same month?
      if (d1.getMonth() === d2.getMonth()) {
          return `${d1.getDate()} - ${d2.getDate()} ${monthNames[d1.getMonth()]}`;
      }
      return `${d1.getDate()} ${monthNames[d1.getMonth()].slice(0,3)} - ${d2.getDate()} ${monthNames[d2.getMonth()].slice(0,3)}`;
  };

  const renderCalendar = () => {
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const daysInMonth = getDaysInMonth(year, month);
    const firstDay = getFirstDayOfMonth(year, month);
    const days = [];

    for (let i = 0; i < firstDay; i++) {
      days.push(<div key={`empty-${i}`} className="h-24 bg-gray-50 border border-gray-100"></div>);
    }

    for (let d = 1; d <= daysInMonth; d++) {
      const currentDayDate = new Date(year, month, d);
      const dateStr = formatDate(currentDayDate);
      const dayEvents = getEventsForDate(currentDayDate);

      let bgClass = "bg-white";
      const term = schoolData.terms.find(t => isDateInRange(dateStr, t.start, t.end));
      if (term && term.isHoliday) bgClass = "bg-red-50";

      // Priority coloring
      const specificHoliday = dayEvents.find(e => e.category === 'holiday' && !e.isTermInfo);
      const exam = dayEvents.find(e => e.category === 'exam');

      if (specificHoliday) bgClass = "bg-red-100";
      else if (exam) bgClass = "bg-yellow-50";

      const isSelected = formatDate(selectedDate) === dateStr;

      days.push(
        <div 
          key={d} 
          onClick={() => setSelectedDate(currentDayDate)}
          className={`h-20 sm:h-28 border border-gray-100 p-1 relative cursor-pointer transition-colors duration-200 
            ${bgClass} hover:bg-blue-50 
            ${isSelected ? 'ring-2 ring-blue-600 z-10' : ''}`}
        >
          <div className="flex justify-between items-start">
            <span className={`text-sm font-semibold rounded-full w-6 h-6 flex items-center justify-center 
              ${isSelected ? 'bg-blue-600 text-white' : 'text-gray-700'}`}>
              {d}
            </span>
            {dayEvents.length > 0 && (
              <div className="flex gap-1">
                {dayEvents.some(e=>e.category === 'exam') && <div className="w-2 h-2 rounded-full bg-yellow-500"></div>}
                {dayEvents.some(e=>e.category === 'meeting') && <div className="w-2 h-2 rounded-full bg-gray-500"></div>}
                {dayEvents.some(e=>e.category === 'program') && <div className="w-2 h-2 rounded-full bg-purple-500"></div>}
                {dayEvents.some(e=>e.category === 'koko') && <div className="w-2 h-2 rounded-full bg-orange-500"></div>}
              </div>
            )}
          </div>

          <div className="hidden sm:block mt-1 space-y-1 overflow-hidden">
            {dayEvents.slice(0, 2).map((evt, idx) => (
              <div key={idx} className={`text-[10px] truncate px-1 rounded ${categoryStyles[evt.category] || categoryStyles.default}`}>
                {evt.title}
              </div>
            ))}
            {dayEvents.length > 2 && (
              <div className="text-[10px] text-gray-500 px-1">+{dayEvents.length - 2} lagi</div>
            )}
          </div>
        </div>
      );
    }
    return days;
  };

  return (
    <div className="min-h-screen bg-gray-100 p-4 font-sans text-slate-800">

      {/* Loading Overlay */}
      {loading && events.length === 0 && (
         <div className="fixed inset-0 bg-white/80 z-50 flex items-center justify-center">
            <div className="flex flex-col items-center gap-3">
               <Loader2 className="w-8 h-8 animate-spin text-blue-600" />
               <p className="text-sm font-medium text-gray-600">Sedang memuat data...</p>
            </div>
         </div>
      )}

      {/* Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={closeModal}></div>
          <div className="bg-white rounded-xl shadow-xl w-full max-w-md relative z-10 overflow-hidden">
            <div className="p-4 border-b border-gray-100 flex justify-between items-center bg-gray-50">
              <h3 className="font-semibold text-lg">{editingEvent ? 'Kemaskini Aktiviti' : 'Tambah Aktiviti Baru'}</h3>
              <button onClick={closeModal} className="p-1 hover:bg-gray-200 rounded-full transition"><X size={20}/></button>
            </div>
            <form onSubmit={saveEvent} className="p-6 space-y-4">
               <div className="grid grid-cols-2 gap-4">
                   <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Tarikh Mula</label>
                      <input 
                        type="date" 
                        required
                        value={formData.start}
                        onChange={e => setFormData({...formData, start: e.target.value})}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition"
                      />
                   </div>
                   <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Tarikh Tamat</label>
                      <input 
                        type="date" 
                        value={formData.end}
                        onChange={e => setFormData({...formData, end: e.target.value})}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition"
                      />
                   </div>
               </div>
               <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Tajuk Aktiviti</label>
                  <input 
                    type="text" 
                    required
                    placeholder="Contoh: Mesyuarat Guru"
                    value={formData.title}
                    onChange={e => setFormData({...formData, title: e.target.value})}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition"
                  />
               </div>
               <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Kategori</label>
                  <select 
                    value={formData.category}
                    onChange={e => setFormData({...formData, category: e.target.value})}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition"
                  >
                    {Object.keys(categoryLabels).map(key => (
                      <option key={key} value={key}>{categoryLabels[key]}</option>
                    ))}
                  </select>
               </div>
               <div className="pt-2 flex justify-end gap-2">
                 <button type="button" onClick={closeModal} className="px-4 py-2 text-gray-600 font-medium hover:bg-gray-100 rounded-lg transition">Batal</button>
                 <button 
                  type="submit" 
                  disabled={isSubmitting}
                  className="px-4 py-2 bg-blue-600 text-white font-medium rounded-lg hover:bg-blue-700 transition flex items-center gap-2 disabled:opacity-70"
                 >
                   {isSubmitting && <Loader2 className="w-4 h-4 animate-spin"/>}
                   {editingEvent ? 'Simpan' : 'Tambah'}
                 </button>
               </div>
            </form>
          </div>
        </div>
      )}

      <div className="max-w-7xl mx-auto grid grid-cols-1 lg:grid-cols-3 gap-6">

        {/* LEFT COLUMN: Calendar & Navigation */}
        <div className="lg:col-span-2 space-y-6">
          <div className="bg-white rounded-2xl shadow-sm p-4 border border-gray-200">
            {/* Header */}
            <div className="flex flex-col sm:flex-row justify-between items-center mb-6 gap-4">
              <div>
                <h1 className="text-2xl font-bold text-slate-800">Takwim SMA Ulu Jempol</h1>
                <p className="text-slate-500 text-sm">Sesi Persekolahan 2026</p>
              </div>

              <div className="flex items-center gap-2 bg-gray-100 p-1 rounded-lg">
                <button onClick={prevMonth} className="p-2 hover:bg-white rounded-md shadow-sm transition"><ChevronLeft size={20}/></button>
                <div className="w-40 text-center font-semibold text-lg">{monthNames[currentDate.getMonth()]} {currentDate.getFullYear()}</div>
                <button onClick={nextMonth} className="p-2 hover:bg-white rounded-md shadow-sm transition"><ChevronRight size={20}/></button>
              </div>
            </div>

            {/* Days Header */}
            <div className="grid grid-cols-7 mb-2 text-center text-sm font-medium text-gray-500">
              <div className="text-red-500">Ahd</div>
              <div>Isn</div>
              <div>Sel</div>
              <div>Rab</div>
              <div>Kha</div>
              <div>Jum</div>
              <div className="text-red-500">Sab</div>
            </div>

            {/* Calendar Grid */}
            <div className="grid grid-cols-7 bg-white border border-gray-200 rounded-lg overflow-hidden">
              {renderCalendar()}
            </div>

            <div className="mt-4 flex flex-wrap gap-3 text-xs text-gray-600 justify-center">
               <span className="flex items-center gap-1"><div className="w-3 h-3 bg-red-100 border border-red-200"></div> Cuti</span>
               <span className="flex items-center gap-1"><div className="w-3 h-3 bg-blue-100 border border-blue-200"></div> Sekolah</span>
               <span className="flex items-center gap-1"><div className="w-3 h-3 bg-yellow-100 border border-yellow-200"></div> Peperiksaan</span>
               <span className="flex items-center gap-1"><div className="w-3 h-3 bg-purple-100 border border-purple-200"></div> Program</span>
               <span className="flex items-center gap-1"><div className="w-3 h-3 bg-green-100 border border-green-200"></div> HEM</span>
            </div>
          </div>
        </div>

        {/* RIGHT COLUMN: Details Panel */}
        <div className="space-y-6">

          {/* Selected Date Details */}
          <div className="bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden">
             <div className="bg-slate-800 text-white p-6 relative">
                <h2 className="text-3xl font-bold">{selectedDate.getDate()}</h2>
                <h3 className="text-xl opacity-90">{monthNames[selectedDate.getMonth()]} {selectedDate.getFullYear()}</h3>
                <p className="opacity-75 mt-1">
                  {['Ahad', 'Isnin', 'Selasa', 'Rabu', 'Khamis', 'Jumaat', 'Sabtu'][selectedDate.getDay()]}
                </p>
                <button 
                  onClick={openAddModal}
                  className="absolute right-6 top-6 bg-blue-600 hover:bg-blue-500 text-white p-2 rounded-full shadow-lg transition-transform hover:scale-105 active:scale-95" 
                  title="Tambah Aktiviti"
                >
                   <Plus size={20} />
                </button>
             </div>

             <div className="p-6">
                <h4 className="font-semibold text-gray-700 mb-4 flex items-center gap-2">
                  <Activity size={18} />
                  Aktiviti Hari Ini
                </h4>

                {selectedEvents.length > 0 ? (
                  <div className="space-y-3">
                    {selectedEvents.map((evt, idx) => (
                      <div key={idx} className={`p-3 rounded-lg border-l-4 text-sm ${categoryStyles[evt.category] || categoryStyles.default} border-l-[color:inherit] bg-opacity-30 group relative`}>
                        <div className="flex items-start gap-2 pr-12">
                          <span className="mt-0.5 opacity-70">{getCategoryIcon(evt.category)}</span>
                          <div>
                            <div className="font-medium">{evt.title}</div>

                            {/* Display Date Range if different */}
                            {evt.start && evt.end && evt.start !== evt.end && (
                                <div className="text-[10px] text-gray-600 mt-1 font-mono flex items-center gap-1">
                                    <Calendar size={10} />
                                    {formatEventDateRange(evt)}
                                </div>
                            )}

                            <div className="text-xs opacity-75 mt-1 uppercase tracking-wider">{categoryLabels[evt.category] || "Umum"}</div>
                          </div>
                        </div>

                        {/* Actions for database events only (those with ID) */}
                        {evt.id && (
                          <div className="absolute right-2 top-2 flex gap-1 opacity-100 sm:opacity-0 group-hover:opacity-100 transition-opacity">
                             <button onClick={() => openEditModal(evt)} className="p-1.5 bg-white text-blue-600 rounded shadow hover:bg-gray-50" title="Edit">
                               <Edit size={14} />
                             </button>
                             <button onClick={() => deleteEvent(evt.id!)} className="p-1.5 bg-white text-red-600 rounded shadow hover:bg-gray-50" title="Padam">
                               <Trash2 size={14} />
                             </button>
                          </div>
                        )}
                      </div>
                    ))}
                  </div>
                ) : (
                  <div className="text-center py-8 text-gray-400">
                    <p>Tiada aktiviti khusus direkodkan.</p>
                    <button onClick={openAddModal} className="mt-4 text-blue-600 text-sm font-medium hover:underline">Tambah Aktiviti +</button>
                  </div>
                )}
             </div>
          </div>

          {/* Quick Stats / Legend / Upcoming */}
          <div className="bg-white rounded-2xl shadow-sm p-6 border border-gray-200">
            <h4 className="font-semibold text-gray-800 mb-4">Sorotan Bulan Ini ({monthNames[currentDate.getMonth()]})</h4>
            <div className="space-y-4">
              {/* Filter events for current month to show quick list */}
              {events
                .filter(e => {
                  if (!e.start) return false;
                  const d = new Date(e.start);
                  return d.getMonth() === currentDate.getMonth() && d.getFullYear() === currentDate.getFullYear();
                })
                .sort((a,b) => {
                    if (!a.start || !b.start) return 0;
                    return new Date(a.start).getTime() - new Date(b.start).getTime();
                })
                .slice(0, 5) // Show top 5
                .map((evt, i) => (
                  <div key={i} className="flex gap-3 items-start group">
                    <div className="bg-gray-100 rounded px-2 py-1 text-center min-w-[3rem]">
                      <div className="text-xs font-bold text-gray-500">{evt.start ? new Date(evt.start).getDate() : '-'}</div>
                      <div className="text-[10px] text-gray-400">{evt.start ? monthNames[new Date(evt.start).getMonth()].substring(0,3) : '-'}</div>
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="text-sm font-medium text-gray-800 leading-tight truncate">{evt.title}</div>
                      <div className="text-xs text-gray-500 mt-1 flex gap-2">
                        <span>{categoryLabels[evt.category]}</span>
                        {evt.end && evt.end !== evt.start && <span className="text-gray-400 text-[10px] flex items-center"><ArrowRight size={8} className="mx-0.5"/> {new Date(evt.end).getDate()}</span>}
                      </div>
                    </div>

                    {/* BUTTONS for Highlights List */}
                    {evt.id && (
                       <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity ml-auto shrink-0 self-center">
                          <button onClick={() => openEditModal(evt)} className="p-1.5 text-blue-600 hover:bg-blue-50 rounded shadow-sm border border-gray-100 bg-white" title="Edit">
                            <Edit size={14} />
                          </button>
                          <button onClick={() => deleteEvent(evt.id!)} className="p-1.5 text-red-600 hover:bg-red-50 rounded shadow-sm border border-gray-100 bg-white" title="Padam">
                            <Trash2 size={14} />
                          </button>
                       </div>
                    )}
                  </div>
                ))
              }
              {events.filter(e => e.start && new Date(e.start).getMonth() === currentDate.getMonth()).length === 0 && (
                 <p className="text-sm text-gray-500 italic">Tiada acara utama disenaraikan bulan ini.</p>
              )}
            </div>
          </div>

        </div>
      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { ChevronLeft, ChevronRight, Calendar, Info, BookOpen, User, Users, Activity, FileText, Plus, Edit, Trash2, X, Loader2, ArrowRight, AlertCircle } from 'lucide-react';

// --- CONFIGURATION ---
const API_URL = "https://script.google.com/macros/s/AKfycbyxauDNUyzxhHLJtDT9gYD5mj88gJADkPCMPFd3JGIfWk34b_xxEftNsbGT4eoEoxxb/exec";

// --- TYPES ---
interface Term {
  name: string;
  start: string;
  end: string;
  isHoliday?: boolean;
}

interface SchoolEvent {
  id?: string; // ID from database
  start?: string; // Replaces 'date'
  end?: string; 
  title: string;
  category: string;
  isTermInfo?: boolean;
  isRecurring?: boolean;
}

interface RecurringEvent {
  day: number;
  type: string;
  desc: string;
}

interface SchoolData {
  terms: Term[];
  recurring: RecurringEvent[];
}

// --- STATIC DATA (Terms & Recurring) ---
const schoolData: SchoolData = {
  terms: [
    { name: "Penggal 1", start: "2026-01-12", end: "2026-03-20" },
    { name: "Cuti Penggal 1", start: "2026-03-21", end: "2026-03-29", isHoliday: true },
    { name: "Penggal 2", start: "2026-03-30", end: "2026-05-22" },
    { name: "Cuti Pertengahan Tahun", start: "2026-05-23", end: "2026-06-07", isHoliday: true },
    { name: "Penggal 3", start: "2026-06-08", end: "2026-08-28" },
    { name: "Cuti Penggal 2", start: "2026-08-29", end: "2026-09-06", isHoliday: true },
    { name: "Penggal 4", start: "2026-09-07", end: "2026-12-04" },
    { name: "Cuti Akhir Persekolahan", start: "2026-12-05", end: "2026-12-31", isHoliday: true },
  ],
  recurring: [
    { day: 1, type: "Kokurikulum", desc: "Perhimpunan Rasmi (Isnin Mg 3, 7:30-8:00)" },
    { day: 3, type: "Sukan", desc: "1M1S/Sukan Permainan (Rabu, 2:00-4:30)" }
  ]
};

// Kategori warna
const categoryStyles: Record<string, string> = {
  academic: "bg-blue-100 text-blue-800 border-blue-200",
  holiday: "bg-red-100 text-red-800 border-red-200",
  exam: "bg-yellow-100 text-yellow-800 border-yellow-200",
  program: "bg-purple-100 text-purple-800 border-purple-200",
  hem: "bg-green-100 text-green-800 border-green-200",
  koko: "bg-orange-100 text-orange-800 border-orange-200",
  meeting: "bg-gray-100 text-gray-800 border-gray-200",
  default: "bg-white text-gray-800 border-gray-100"
};

const categoryLabels: Record<string, string> = {
  academic: "Akademik/Sekolah",
  holiday: "Cuti",
  exam: "Peperiksaan",
  program: "Program Sekolah",
  hem: "Hal Ehwal Murid",
  koko: "Kokurikulum",
  meeting: "Mesyuarat"
};

const getCategoryIcon = (cat: string) => {
  switch(cat) {
    case 'academic': return <BookOpen className="w-4 h-4" />;
    case 'holiday': return <Calendar className="w-4 h-4" />;
    case 'exam': return <FileText className="w-4 h-4" />;
    case 'program': return <Activity className="w-4 h-4" />;
    case 'hem': return <User className="w-4 h-4" />;
    case 'koko': return <Activity className="w-4 h-4" />;
    case 'meeting': return <Users className="w-4 h-4" />;
    default: return <Info className="w-4 h-4" />;
  }
};

export default function App() {
  const getInitialDate = () => {
    const today = new Date();
    // Default to 2026 for this specific calendar app
    return new Date(2026, today.getMonth(), today.getDate());
  };

  const [currentDate, setCurrentDate] = useState<Date>(getInitialDate()); 
  const [selectedDate, setSelectedDate] = useState<Date>(getInitialDate());
  const [events, setEvents] = useState<SchoolEvent[]>([]); // Dynamic events from DB
  const [loading, setLoading] = useState(true);

  // Modal State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false); // State untuk modal delete
  const [eventToDeleteId, setEventToDeleteId] = useState<string | null>(null); // ID untuk dipadam

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [editingEvent, setEditingEvent] = useState<SchoolEvent | null>(null);
  const [formData, setFormData] = useState({ title: '', category: 'academic', start: '', end: '' });

  // --- API FUNCTIONS ---

  const fetchEvents = async () => {
    setLoading(true);
    try {
      const response = await fetch(API_URL);
      const result = await response.json();
      if (result.status === 'success') {
        setEvents(result.data);
      } else {
        console.error("Failed to fetch:", result.message);
      }
    } catch (error) {
      console.error("Error fetching events:", error);
    } finally {
      setLoading(false);
    }
  };

  const saveEvent = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);

    // Validate end date is not before start date
    if (formData.end && formData.start && formData.end < formData.start) {
        alert("Tarikh tamat tidak boleh sebelum tarikh mula.");
        setIsSubmitting(false);
        return;
    }

    try {
      const action = editingEvent ? 'update' : 'create';
      const payload = {
        action,
        id: editingEvent ? editingEvent.id : undefined,
        title: formData.title,
        category: formData.category,
        start: formData.start,
        end: formData.end || formData.start // If end is empty, assume single day
      };

      await fetch(API_URL, {
        method: 'POST',
        body: JSON.stringify(payload),
      });

      await fetchEvents();
      closeModal();
    } catch (error) {
      console.error("Error saving:", error);
      alert("Ralat menyimpan data. Sila cuba lagi.");
    } finally {
      setIsSubmitting(false);
    }
  };

  // Trigger modal delete
  const openDeleteModal = (id: string) => {
    setEventToDeleteId(id);
    setIsDeleteModalOpen(true);
  };

  const closeDeleteModal = () => {
    setIsDeleteModalOpen(false);
    setEventToDeleteId(null);
  }

  // Execute delete action
  const confirmDelete = async () => {
    if(!eventToDeleteId) return;

    setIsSubmitting(true); 
    try {
      await fetch(API_URL, {
        method: 'POST',
        body: JSON.stringify({ action: 'delete', id: eventToDeleteId }),
      });
      await fetchEvents();
      closeDeleteModal();
    } catch (error) {
      console.error("Error deleting:", error);
      alert("Ralat memadam data.");
    } finally {
      setIsSubmitting(false);
    }
  };

  useEffect(() => {
    fetchEvents();
  }, []);

  // --- CALENDAR LOGIC ---

  const getDaysInMonth = (year: number, month: number) => new Date(year, month + 1, 0).getDate();
  const getFirstDayOfMonth = (year: number, month: number) => new Date(year, month, 1).getDay();
  const formatDate = (date: Date) => date.toISOString().split('T')[0];

  const isDateInRange = (dateStr: string, startStr: string, endStr: string) => {
    return dateStr >= startStr && dateStr <= endStr;
  };

  const getEventsForDate = (date: Date): SchoolEvent[] => {
    const dateStr = formatDate(date);

    // 1. Database Events (Check range overlap)
    let dailyEvents: SchoolEvent[] = events.filter(e => {
        if (!e.start) return false;
        const end = e.end || e.start;
        return dateStr >= e.start && dateStr <= end;
    });

    // 2. School Terms
    const term = schoolData.terms.find(t => isDateInRange(dateStr, t.start, t.end));
    if (term) {
      if (dailyEvents.length === 0 || term.isHoliday) {
        dailyEvents.push({
          title: term.name,
          category: term.isHoliday ? 'holiday' : 'academic',
          isTermInfo: true
        });
      }
    }

    // 3. Recurring Events (Only if term exists and not a holiday)
    if (term && !term.isHoliday) {
      const dayOfWeek = date.getDay();
      if (dayOfWeek === 3) {
         dailyEvents.push({ title: "1M1S / Sukan Permainan (2:00 ptg)", category: "koko", isRecurring: true });
      }
      if (dayOfWeek === 1 && date.getDate() >= 15 && date.getDate() <= 21) {
         dailyEvents.push({ title: "Perhimpunan Rasmi Kokurikulum", category: "koko", isRecurring: true });
      }
    }

    return dailyEvents;
  };

  const [selectedEvents, setSelectedEvents] = useState<SchoolEvent[]>([]);

  useEffect(() => {
    const evts = getEventsForDate(selectedDate);
    setSelectedEvents(evts);
  }, [selectedDate, events]);

  const nextMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));
  const prevMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));

  const monthNames = [
    "Januari", "Februari", "Mac", "April", "Mei", "Jun",
    "Julai", "Ogos", "September", "Oktober", "November", "Disember"
  ];

  // --- MODAL HELPERS ---
  const openAddModal = () => {
    setEditingEvent(null);
    const dateStr = formatDate(selectedDate);
    setFormData({
      title: '',
      category: 'program',
      start: dateStr,
      end: dateStr
    });
    setIsModalOpen(true);
  };

  const openEditModal = (evt: SchoolEvent) => {
    setEditingEvent(evt);
    setFormData({
      title: evt.title,
      category: evt.category,
      start: evt.start || '',
      end: evt.end || evt.start || ''
    });
    setIsModalOpen(true);
  };

  const closeModal = () => {
    setIsModalOpen(false);
    setEditingEvent(null);
  };

  // Helper to display date range cleanly
  const formatEventDateRange = (evt: SchoolEvent) => {
      if (!evt.start) return "";
      const d1 = new Date(evt.start);
      if (!evt.end || evt.start === evt.end) {
          return `${d1.getDate()} ${monthNames[d1.getMonth()]}`;
      }
      const d2 = new Date(evt.end);
      // Same month?
      if (d1.getMonth() === d2.getMonth()) {
          return `${d1.getDate()} - ${d2.getDate()} ${monthNames[d1.getMonth()]}`;
      }
      return `${d1.getDate()} ${monthNames[d1.getMonth()].slice(0,3)} - ${d2.getDate()} ${monthNames[d2.getMonth()].slice(0,3)}`;
  };

  const renderCalendar = () => {
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const daysInMonth = getDaysInMonth(year, month);
    const firstDay = getFirstDayOfMonth(year, month);
    const days = [];

    for (let i = 0; i < firstDay; i++) {
      days.push(<div key={`empty-${i}`} className="h-24 bg-gray-50 border border-gray-100"></div>);
    }

    for (let d = 1; d <= daysInMonth; d++) {
      const currentDayDate = new Date(year, month, d);
      const dateStr = formatDate(currentDayDate);
      const dayEvents = getEventsForDate(currentDayDate);

      let bgClass = "bg-white";
      const term = schoolData.terms.find(t => isDateInRange(dateStr, t.start, t.end));
      if (term && term.isHoliday) bgClass = "bg-red-50";

      // Priority coloring
      const specificHoliday = dayEvents.find(e => e.category === 'holiday' && !e.isTermInfo);
      const exam = dayEvents.find(e => e.category === 'exam');

      if (specificHoliday) bgClass = "bg-red-100";
      else if (exam) bgClass = "bg-yellow-50";

      const isSelected = formatDate(selectedDate) === dateStr;

      days.push(
        <div 
          key={d} 
          onClick={() => setSelectedDate(currentDayDate)}
          className={`h-20 sm:h-28 border border-gray-100 p-1 relative cursor-pointer transition-colors duration-200 
            ${bgClass} hover:bg-blue-50 
            ${isSelected ? 'ring-2 ring-blue-600 z-10' : ''}`}
        >
          <div className="flex justify-between items-start">
            <span className={`text-sm font-semibold rounded-full w-6 h-6 flex items-center justify-center 
              ${isSelected ? 'bg-blue-600 text-white' : 'text-gray-700'}`}>
              {d}
            </span>
            {dayEvents.length > 0 && (
              <div className="flex gap-1">
                {dayEvents.some(e=>e.category === 'exam') && <div className="w-2 h-2 rounded-full bg-yellow-500"></div>}
                {dayEvents.some(e=>e.category === 'meeting') && <div className="w-2 h-2 rounded-full bg-gray-500"></div>}
                {dayEvents.some(e=>e.category === 'program') && <div className="w-2 h-2 rounded-full bg-purple-500"></div>}
                {dayEvents.some(e=>e.category === 'koko') && <div className="w-2 h-2 rounded-full bg-orange-500"></div>}
              </div>
            )}
          </div>

          <div className="hidden sm:block mt-1 space-y-1 overflow-hidden">
            {dayEvents.slice(0, 2).map((evt, idx) => (
              <div key={idx} className={`text-[10px] truncate px-1 rounded ${categoryStyles[evt.category] || categoryStyles.default}`}>
                {evt.title}
              </div>
            ))}
            {dayEvents.length > 2 && (
              <div className="text-[10px] text-gray-500 px-1">+{dayEvents.length - 2} lagi</div>
            )}
          </div>
        </div>
      );
    }
    return days;
  };

  return (
    <div className="min-h-screen bg-gray-100 p-4 font-sans text-slate-800">

      {/* Loading Overlay */}
      {loading && events.length === 0 && (
         <div className="fixed inset-0 bg-white/80 z-50 flex items-center justify-center">
            <div className="flex flex-col items-center gap-3">
               <Loader2 className="w-8 h-8 animate-spin text-blue-600" />
               <p className="text-sm font-medium text-gray-600">Sedang memuat data...</p>
            </div>
         </div>
      )}

      {/* Delete Confirmation Modal */}
      {isDeleteModalOpen && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={closeDeleteModal}></div>
          <div className="bg-white rounded-xl shadow-xl w-full max-w-sm relative z-10 overflow-hidden transform transition-all scale-100">
            <div className="p-6 flex flex-col items-center text-center">
              <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center mb-4">
                <AlertCircle className="w-6 h-6 text-red-600" />
              </div>
              <h3 className="text-lg font-bold text-gray-900 mb-2">Padam Aktiviti?</h3>
              <p className="text-sm text-gray-500 mb-6">
                Adakah anda pasti mahu memadam aktiviti ini? Tindakan ini tidak boleh dikembalikan.
              </p>
              <div className="flex gap-3 w-full">
                <button 
                  onClick={closeDeleteModal}
                  className="flex-1 px-4 py-2 bg-gray-100 hover:bg-gray-200 text-gray-700 font-medium rounded-lg transition"
                >
                  Batal
                </button>
                <button 
                  onClick={confirmDelete}
                  disabled={isSubmitting}
                  className="flex-1 px-4 py-2 bg-red-600 hover:bg-red-700 text-white font-medium rounded-lg transition flex items-center justify-center gap-2"
                >
                  {isSubmitting ? <Loader2 className="w-4 h-4 animate-spin"/> : "Padam"}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Add/Edit Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={closeModal}></div>
          <div className="bg-white rounded-xl shadow-xl w-full max-w-md relative z-10 overflow-hidden">
            <div className="p-4 border-b border-gray-100 flex justify-between items-center bg-gray-50">
              <h3 className="font-semibold text-lg">{editingEvent ? 'Kemaskini Aktiviti' : 'Tambah Aktiviti Baru'}</h3>
              <button onClick={closeModal} className="p-1 hover:bg-gray-200 rounded-full transition"><X size={20}/></button>
            </div>
            <form onSubmit={saveEvent} className="p-6 space-y-4">
               <div className="grid grid-cols-2 gap-4">
                   <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Tarikh Mula</label>
                      <input 
                        type="date" 
                        required
                        value={formData.start}
                        onChange={e => setFormData({...formData, start: e.target.value})}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition"
                      />
                   </div>
                   <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Tarikh Tamat</label>
                      <input 
                        type="date" 
                        value={formData.end}
