// Helper: Menjana tarikh Kokurikulum 2026
function getKokoEvents2026() {
  const events = [];
  const year = 2026;

  // Loop setiap hari dalam tahun 2026
  let d = new Date(year, 0, 1);
  while (d.getFullYear() === year) {
    const day = d.getDay(); // 0=Sun, 1=Mon, ..., 3=Wed
    const dateStr = formatDateForSheet(d); 
    const month = d.getMonth(); // 0-11
    const date = d.getDate();

    // Hadkan sehingga tamat sekolah (4 Disember)
    if (month < 11 || (month === 11 && date <= 4)) {

      // RABU: 1M1S / Sukan Permainan
      if (day === 3) {
         events.push({ date: dateStr, title: "1M1S / Sukan Permainan (2:00 ptg)", category: "koko" });
      }

      // ISNIN: Perhimpunan Rasmi Kokurikulum (Minggu ke-3)
      // Minggu ke-3 ialah apabila tarikh antara 15 hingga 21
      if (day === 1 && date >= 15 && date <= 21) {
         events.push({ date: dateStr, title: "Perhimpunan Rasmi Kokurikulum", category: "koko" });
      }
    }

    d.setDate(d.getDate() + 1);
  }
  return events;
}

// Format tarikh untuk sheet YYYY-MM-DD
function formatDateForSheet(dateObj) {
    const year = dateObj.getFullYear();
    const month = String(dateObj.getMonth() + 1).padStart(2, '0');
    const day = String(dateObj.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
}

// Setup sheet jika belum wujud atau kosong
function setupSheet() {
  const ss = SpreadsheetApp.openById(SHEET_ID);
  let sheet = ss.getSheetByName(SHEET_NAME);

  if (!sheet) {
    sheet = ss.insertSheet(SHEET_NAME);
    // Header row dengan dua column tarikh
    sheet.appendRow(['id', 'start_date', 'end_date', 'title', 'category']);
    // Format header
    sheet.getRange(1, 1, 1, 5).setFontWeight('bold').setBackground('#f3f4f6');
  }

  return sheet;
}

// Fungsi untuk memasukkan data seed
function populateSeedData(sheet) {
  const kokoEvents = getKokoEvents2026();
  // Gabungkan manual events dan koko events
  const allEvents = [...SEED_DATA, ...kokoEvents];

  const dataToInsert = allEvents.map(item => {
    // Untuk seed data, start = end (acara satu hari)
    return [Utilities.getUuid(), item.date, item.date, item.title, item.category];
  });

  if (dataToInsert.length > 0) {
    sheet.getRange(2, 1, dataToInsert.length, 5).setValues(dataToInsert);
  }
}

// CREATE / UPDATE / DELETE / BULK
function doPost(e) {
  const lock = LockService.getScriptLock();
  lock.tryLock(30000); // 30 sec lock for bulk operations

  try {
    const sheet = setupSheet();
    const data = JSON.parse(e.postData.contents);
    const action = data.action;

    if (action === 'create') {
      const id = Utilities.getUuid();
      const endDate = data.end || data.start;
      sheet.appendRow([id, data.start, endDate, data.title, data.category]);
      return response({ status: 'success', message: 'Event created', id: id });
    }

    else if (action === 'bulk_create') {
      const newEvents = data.events; // Expecting array of objects {title, start, end, category}
      if (!newEvents || !Array.isArray(newEvents) || newEvents.length === 0) {
        return response({ status: 'error', message: 'No events provided' });
      }

      // Read existing data to check for duplicates
      const rows = sheet.getDataRange().getValues();
      const headers = rows.shift(); // Remove header

      // Create a signature Set for existing events: "YYYY-MM-DD|TITLE" (Lowercased title)
      const existingSignatures = new Set();
      rows.forEach(row => {
        const dateStr = formatDate(row[1]); // start_date
        const titleStr = String(row[3]).trim().toLowerCase();
        existingSignatures.add(`${dateStr}|${titleStr}`);
      });

      const eventsToAdd = [];
      let addedCount = 0;
      let duplicateCount = 0;

      newEvents.forEach(evt => {
        const evtStart = evt.start;
        const evtEnd = evt.end || evt.start;
        const evtTitle = String(evt.title).trim();
        const signature = `${evtStart}|${evtTitle.toLowerCase()}`;

        if (!existingSignatures.has(signature)) {
            const id = Utilities.getUuid();
            eventsToAdd.push([id, evtStart, evtEnd, evtTitle, evt.category || 'academic']);
            // Add to signature to prevent duplicates within the bulk batch itself
            existingSignatures.add(signature);
            addedCount++;
        } else {
            duplicateCount++;
        }
      });

      if (eventsToAdd.length > 0) {
        sheet.getRange(sheet.getLastRow() + 1, 1, eventsToAdd.length, 5).setValues(eventsToAdd);
      }

      return response({ 
        status: 'success', 
        message: 'Bulk process complete', 
        added: addedCount, 
        duplicates: duplicateCount 
      });
    }

    else if (action === 'update') {
      const rows = sheet.getDataRange().getValues();
      const headers = rows.shift(); 

      const rowIndex = rows.findIndex(r => r[0] === data.id);

      if (rowIndex === -1) {
        return response({ status: 'error', message: 'ID not found' });
      }

      const endDate = data.end || data.start;
      const range = sheet.getRange(rowIndex + 2, 1, 1, 5);
      range.setValues([[data.id, data.start, endDate, data.title, data.category]]);

      return response({ status: 'success', message: 'Event updated' });
    }

    else if (action === 'delete') {
      const rows = sheet.getDataRange().getValues();
      const headers = rows.shift();
      const rowIndex = rows.findIndex(r => r[0] === data.id);

      if (rowIndex === -1) {
        return response({ status: 'error', message: 'ID not found' });
      }

      sheet.deleteRow(rowIndex + 2);
      return response({ status: 'success', message: 'Event deleted' });
    }

    return response({ status: 'error', message: 'Invalid action' });

  } catch (error) {
    return response({ status: 'error', message: error.toString() });
  } finally {
    lock.releaseLock();
  }
}

// READ
function doGet(e) {
  try {
    const sheet = setupSheet();
    let rows = sheet.getDataRange().getValues();

    if (rows.length <= 1) {
       populateSeedData(sheet);
       rows = sheet.getDataRange().getValues();
    }

    const headers = rows.shift();

    const events = rows.map(row => ({
      id: row[0],
      start: formatDate(row[1]),
      end: formatDate(row[2]),
      title: row[3],
      category: row[4]
    })).filter(e => e.id && e.start);

    return response({ status: 'success', data: events });

  } catch (error) {
    return response({ status: 'error', message: error.toString() });
  }
}

function response(data) {
  return ContentService
    .createTextOutput(JSON.stringify(data))
    .setMimeType(ContentService.MimeType.JSON);
}

function formatDate(dateObj) {
  if (!dateObj) return "";
  if (typeof dateObj === 'string') return dateObj.substring(0, 10);

  try {
    const year = dateObj.getFullYear();
    const month = String(dateObj.getMonth() + 1).padStart(2, '0');
    const day = String(dateObj.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  } catch (e) {
    return String(dateObj);
  }
}

