// Helper: Menjana tarikh Kokurikulum 2026
function getKokoEvents2026() {
  const events = [];
  const year = 2026;
  let d = new Date(year, 0, 1);
  while (d.getFullYear() === year) {
    const day = d.getDay(); 
    const dateStr = formatDateForSheet(d); 
    const month = d.getMonth(); 
    const date = d.getDate();

    if (month < 11 || (month === 11 && date <= 4)) {
      if (day === 3) {
         events.push({ date: dateStr, title: "1M1S / Sukan Permainan (2:00 ptg)", category: "koko" });
      }
      if (day === 1 && date >= 15 && date <= 21) {
         events.push({ date: dateStr, title: "Perhimpunan Rasmi Kokurikulum", category: "koko" });
      }
    }
    d.setDate(d.getDate() + 1);
  }
  return events;
}

function formatDateForSheet(dateObj) {
    const year = dateObj.getFullYear();
    const month = String(dateObj.getMonth() + 1).padStart(2, '0');
    const day = String(dateObj.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
}

function setupSheet() {
  const ss = SpreadsheetApp.openById(SHEET_ID);
  let sheet = ss.getSheetByName(SHEET_NAME);

  if (!sheet) {
    sheet = ss.insertSheet(SHEET_NAME);
    sheet.appendRow(['id', 'start_date', 'end_date', 'title', 'category']);
    sheet.getRange(1, 1, 1, 5).setFontWeight('bold').setBackground('#f3f4f6');
  }
  return sheet;
}

function populateSeedData(sheet) {
  const kokoEvents = getKokoEvents2026();
  const allEvents = [...SEED_DATA, ...kokoEvents];

  const dataToInsert = allEvents.map(item => {
    return [Utilities.getUuid(), item.date, item.date, item.title, item.category];
  });

  if (dataToInsert.length > 0) {
    sheet.getRange(2, 1, dataToInsert.length, 5).setValues(dataToInsert);
  }
}

