      <div className="bg-gray-50 min-h-[300px] max-h-[600px] overflow-y-auto p-4 custom-scrollbar">
        {filteredEvents.length > 0 ? (
            <div className="space-y-3">
                {filteredEvents.map((evt, idx) => (
                    <div 
                        key={evt.id || idx} 
                        className="bg-white p-4 rounded-xl shadow-sm border border-gray-100 flex flex-col sm:flex-row gap-4 items-start sm:items-center hover:shadow-md transition-shadow group"
                    >
                        {/* Date Box */}
                        <div className="flex sm:flex-col items-center justify-center bg-gray-100 rounded-lg p-2 min-w-[4rem] sm:min-w-[5rem] text-center shrink-0 gap-2 sm:gap-0">
                             <span className="text-xs font-bold text-gray-500 uppercase">
                                {evt.start ? new Date(evt.start).toLocaleString('ms-MY', { month: 'short' }) : '-'}
                             </span>
                             <span className="text-xl sm:text-2xl font-bold text-gray-800 leading-none">
                                {evt.start ? new Date(evt.start).getDate() : '-'}
                             </span>
                        </div>

                        {/* Content */}
                        <div className="flex-1 min-w-0">
                            <div className="flex items-center gap-2 mb-1">
                                <span className={`text-[10px] px-2 py-0.5 rounded-full font-medium border ${CATEGORY_STYLES[evt.category]?.replace('bg-', 'bg-opacity-20 ')}`}>
                                    {CATEGORY_LABELS[evt.category]}
                                </span>
                            </div>
                            <h4 className="font-semibold text-gray-800 text-sm sm:text-base mb-1">{evt.title}</h4>
                            <div className="flex items-center gap-4 text-xs text-gray-500">
                                <span className="flex items-center gap-1">
                                    <Calendar size={12} />
                                    {formatEventDateRange(evt)}
                                </span>
                            </div>
                        </div>

                        {/* Actions */}
                        <div className="flex items-center gap-2 w-full sm:w-auto justify-end border-t sm:border-t-0 pt-3 sm:pt-0 mt-2 sm:mt-0 border-gray-100">
                            {/* Butang Tambah ke Takwim Rasmi (Hanya untuk Draf) */}
                            {activeTab === 'draft' && (
                                <button 
                                    onClick={() => openCopyModal(evt)}
                                    className="p-2 text-emerald-600 bg-emerald-50 hover:bg-emerald-100 rounded-lg transition border border-emerald-100"
                                    title="Tambah ke Takwim Rasmi"
                                    disabled={copyingId === evt.id}
                                >
                                    {copyingId === evt.id ? <Loader2 size={16} className="animate-spin" /> : <CalendarPlus size={16} />}
                                </button>
                            )}

                            <button 
                                onClick={() => openEditModal(evt)}
                                className="p-2 text-blue-600 bg-blue-50 hover:bg-blue-100 rounded-lg transition"
                                title="Edit"
                            >
                                <Edit size={16} />
                            </button>
                            <button 
                                onClick={() => evt.id && openDeleteModal(evt.id)}
                                className="p-2 text-red-600 bg-red-50 hover:bg-red-100 rounded-lg transition"
                                title="Padam"
                            >
                                <Trash2 size={16} />
                            </button>
                        </div>
                    </div>
                ))}
            </div>
        ) : (
            <div className="flex flex-col items-center justify-center h-64 text-gray-400">
                <Calendar size={48} className="mb-4 opacity-20" />
                <p>Tiada acara dalam kategori ini.</p>
                <button 
                    onClick={() => openAddModal(activeCategory === 'all' ? 'program' : activeCategory)}
                    className="mt-2 text-blue-600 text-sm font-medium hover:underline"
                >
                    Tambah Acara Baru
                </button>
            </div>
        )}
      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { Loader2, Sparkles } from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";

import Header from './components/Header';
import CalendarSection from './components/CalendarSection';
import Sidebar from './components/Sidebar';
import EventListSection from './components/EventListSection';
import { AddEditModal, DeleteModal, CopyModal, AIModal } from './components/Modals';

import { SchoolEvent } from './types';
import { API_URL, SCHOOL_DATA } from './constants';
import { formatDate, getEventsForDate } from './utils';

export default function App() {
  const getInitialDate = () => {
    const today = new Date();
    // Default to 2026 for this specific calendar app
    return new Date(2026, today.getMonth(), today.getDate());
  };

  const [activeTab, setActiveTab] = useState<'draft' | 'public'>('draft');
  const [currentDate, setCurrentDate] = useState<Date>(getInitialDate()); 
  const [selectedDate, setSelectedDate] = useState<Date>(getInitialDate());

  const [draftEvents, setDraftEvents] = useState<SchoolEvent[]>([]);
  const [publicEvents, setPublicEvents] = useState<SchoolEvent[]>([]);

  const [loading, setLoading] = useState(true);

  // Modal State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [eventToDeleteId, setEventToDeleteId] = useState<string | null>(null);

  // AI Modal State
  const [isAIModalOpen, setIsAIModalOpen] = useState(false);
  const [aiInputText, setAiInputText] = useState("");
  const [isProcessingAI, setIsProcessingAI] = useState(false);

  // Copy Modal State
  const [isCopyModalOpen, setIsCopyModalOpen] = useState(false);
  const [eventToCopy, setEventToCopy] = useState<SchoolEvent | null>(null);

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [editingEvent, setEditingEvent] = useState<SchoolEvent | null>(null);
  const [formData, setFormData] = useState({ title: '', category: 'academic', start: '', end: '' });

  // --- API FUNCTIONS ---

  const fetchDraftEvents = async () => {
    setLoading(true);
    try {
      const response = await fetch(API_URL);
      const result = await response.json();
      if (result.status === 'success') {
        setDraftEvents(result.data);
      } else {
        console.error("Failed to fetch draft:", result.message);
      }
    } catch (error) {
      console.error("Error fetching draft events:", error);
    } finally {
      setLoading(false);
    }
  };

  const fetchPublicEvents = async () => {
    setLoading(true);
    try {
        const response = await fetch(`${API_URL}?source=gcal`);
        const result = await response.json();

        if (result.status === 'success') {
            setPublicEvents(result.data);
        } else {
            console.warn("GCal fetch warning:", result.message);
            setPublicEvents([]);
        }
    } catch (error) {
        console.error("Error fetching public GCal events:", error);
    } finally {
        setLoading(false);
    }
  };

  const saveEvent = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);

    if (formData.end && formData.start && formData.end < formData.start) {
        alert("Tarikh tamat tidak boleh sebelum tarikh mula.");
        setIsSubmitting(false);
        return;
    }

    try {
      const action = editingEvent ? 'update' : 'create';
      const payload = {
        action,
        source: activeTab === 'public' ? 'gcal' : 'draft',
        id: editingEvent ? editingEvent.id : undefined,
        title: formData.title,
        category: formData.category,
        start: formData.start,
        end: formData.end || formData.start
      };

      await fetch(API_URL, {
        method: 'POST',
        body: JSON.stringify(payload),
      });

      if (activeTab === 'public') {
          await fetchPublicEvents();
      } else {
          await fetchDraftEvents();
      }
      closeModal();
    } catch (error) {
      console.error("Error saving:", error);
      alert("Ralat menyimpan data. Sila cuba lagi.");
    } finally {
      setIsSubmitting(false);
    }
  };

  // Trigger modal delete
  const openDeleteModal = (id: string) => {
    setEventToDeleteId(id);
    setIsDeleteModalOpen(true);
  };

  const confirmDelete = async () => {
    if(!eventToDeleteId) return;

    setIsSubmitting(true); 
    try {
      await fetch(API_URL, {
        method: 'POST',
        body: JSON.stringify({ 
            action: 'delete', 
            id: eventToDeleteId,
            source: activeTab === 'public' ? 'gcal' : 'draft' 
        }),
      });

      if (activeTab === 'public') {
          await fetchPublicEvents();
      } else {
          await fetchDraftEvents();
      }
      setIsDeleteModalOpen(false);
      setEventToDeleteId(null);
    } catch (error) {
      console.error("Error deleting:", error);
      alert("Ralat memadam data.");
    } finally {
      setIsSubmitting(false);
    }
  };

  // --- COPY TO GCAL LOGIC ---
  const openCopyModal = (evt: SchoolEvent) => {
      setEventToCopy(evt);
      setIsCopyModalOpen(true);
  };

  const confirmCopy = async () => {
    if (!eventToCopy || !eventToCopy.id) return;
    setIsSubmitting(true);

    try {
        await fetch(API_URL, {
            method: 'POST',
            body: JSON.stringify({
                action: 'copy_to_gcal',
                id: eventToCopy.id
            }),
        });

        await fetchPublicEvents();
        setIsCopyModalOpen(false);
        setEventToCopy(null);
        alert(`"${eventToCopy.title}" berjaya ditambah ke Takwim Rasmi (Google Calendar).`);
    } catch (error) {
        console.error("Error copying to GCal:", error);
        alert("Gagal menyalin ke Google Calendar.");
    } finally {
        setIsSubmitting(false);
    }
  };

  // --- AI LOGIC ---
  const handleAIProcess = async () => {
    if (!aiInputText.trim()) return;
    setIsProcessingAI(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `
        Anda adalah pembantu takwim sekolah. Ekstrak senarai acara dari teks yang diberikan ke dalam format JSON.

        Kategori yang dibenarkan:
        - academic (untuk persekolahan, kelas, bengkel)
        - holiday (cuti, pelepasan)
        - exam (peperiksaan, ujian)
        - program (program sekolah, sambutan)
        - hem (hal ehwal murid, asrama, disiplin)
        - koko (sukan, kelab, persatuan)
        - meeting (mesyuarat)

        Jika kategori tidak jelas, gunakan 'program'.
        Tarikh mesti dalam format YYYY-MM-DD. Jika tiada tarikh tamat, gunakan tarikh mula sebagai tarikh tamat.
        Tahun semasa adalah 2026.

        Teks Input:
        "${aiInputText}"
      `;

      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash",
        contents: prompt,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                title: { type: Type.STRING },
                start: { type: Type.STRING },
                end: { type: Type.STRING },
                category: { type: Type.STRING }
              },
              required: ["title", "start", "category"]
            }
          }
        }
      });

      const extractedEvents = JSON.parse(response.text);

      if (extractedEvents.length > 0) {
        const apiResponse = await fetch(API_URL, {
          method: 'POST',
          body: JSON.stringify({ 
              action: 'bulk_create', 
              events: extractedEvents,
              source: activeTab === 'public' ? 'gcal' : 'draft'
          }),
        });

        const result = await apiResponse.json();

        if (result.status === 'success') {
          alert(`Proses Selesai!\n${result.added} acara ditambah.\n${result.duplicates} acara diabaikan (duplikasi).`);
          if (activeTab === 'public') await fetchPublicEvents();
          else await fetchDraftEvents();

          setAiInputText("");
          setIsAIModalOpen(false);
        } else {
          alert("Ralat menyimpan data ke pangkalan data.");
        }
      } else {
        alert("Tiada acara dapat diekstrak dari teks tersebut.");
      }

    } catch (error) {
      console.error("AI Processing Error:", error);
      alert("Berlaku ralat semasa memproses AI. Sila cuba lagi.");
    } finally {
      setIsProcessingAI(false);
    }
  };

  useEffect(() => {
    fetchDraftEvents();
    fetchPublicEvents();
  }, []);

  const [selectedEvents, setSelectedEvents] = useState<SchoolEvent[]>([]);

  // Navigation Logic
  const nextMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));
  const prevMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));

  // Modals Open Logic
  const openAddModal = (preselectedCategory?: string) => {
    setEditingEvent(null);
    const dateStr = formatDate(selectedDate);
    setFormData({
      title: '',
      category: preselectedCategory || 'program',
      start: dateStr,
      end: dateStr
    });
    setIsModalOpen(true);
  };

  const openEditModal = (evt: SchoolEvent) => {
    setEditingEvent(evt);
    setFormData({
      title: evt.title,
      category: evt.category,
      start: evt.start || '',
      end: evt.end || evt.start || ''
    });
    setIsModalOpen(true);
  };

  const closeModal = () => {
    setIsModalOpen(false);
    setEditingEvent(null);
  };

  const activeEventsList = activeTab === 'draft' ? draftEvents : publicEvents;

  useEffect(() => {
    const evts = getEventsForDate(selectedDate, activeEventsList, SCHOOL_DATA.terms);
    setSelectedEvents(evts);
  }, [selectedDate, draftEvents, publicEvents, activeTab]);

  return (
    <div className="min-h-screen bg-gray-100 font-sans text-slate-800">

      <Header activeTab={activeTab} setActiveTab={setActiveTab} />

      <div className="pt-20 p-4">

      {/* Loading Overlay */}
      {loading && activeEventsList.length === 0 && (
         <div className="fixed inset-0 bg-white/80 z-50 flex items-center justify-center">
            <div className="flex flex-col items-center gap-3">
               <Loader2 className="w-8 h-8 animate-spin text-blue-600" />
               <p className="text-sm font-medium text-gray-600">Sedang memuat data...</p>
            </div>
         </div>
      )}

      {/* AI Processing Overlay */}
      {isProcessingAI && (
         <div className="fixed inset-0 bg-white/90 z-[70] flex items-center justify-center">
            <div className="flex flex-col items-center gap-4 animate-pulse">
               <Sparkles className="w-12 h-12 text-purple-600 animate-spin" />
               <div className="text-center">
                  <p className="text-lg font-bold text-gray-800">Sedang Memproses...</p>
                  <p className="text-sm text-gray-500">AI sedang membaca jadual anda dan menyimpannya.</p>
               </div>
            </div>
         </div>
      )}

      {/* MODALS */}
      <AIModal 
        isOpen={isAIModalOpen} 
        onClose={() => setIsAIModalOpen(false)} 
        activeTab={activeTab}
        aiInputText={aiInputText}
        setAiInputText={setAiInputText}
        isProcessingAI={isProcessingAI}
        handleAIProcess={handleAIProcess}
      />

      <AddEditModal 
        isOpen={isModalOpen} 
        onClose={closeModal} 
        onSubmit={saveEvent}
        formData={formData}
        setFormData={setFormData}
        isSubmitting={isSubmitting}
        editingEvent={editingEvent}
        activeTab={activeTab}
      />

      <DeleteModal 
        isOpen={isDeleteModalOpen} 
        onClose={() => setIsDeleteModalOpen(false)} 
        onConfirm={confirmDelete}
        isSubmitting={isSubmitting}
        activeTab={activeTab}
      />

      <CopyModal 
        isOpen={isCopyModalOpen} 
        onClose={() => setIsCopyModalOpen(false)} 
        onConfirm={confirmCopy}
        isSubmitting={isSubmitting}
        eventToCopy={eventToCopy}
      />

      <div className="max-w-7xl mx-auto grid grid-cols-1 lg:grid-cols-3 gap-6">

        {/* LEFT COLUMN: Calendar & Navigation */}
        <div className="lg:col-span-2 space-y-6">
          <CalendarSection 
            currentDate={currentDate}
            selectedDate={selectedDate}
            setSelectedDate={setSelectedDate}
            activeTab={activeTab}
            prevMonth={prevMonth}
            nextMonth={nextMonth}
            activeEventsList={activeEventsList}
            terms={SCHOOL_DATA.terms}
            loading={loading}
          />

          <EventListSection 
            events={activeEventsList}
            activeTab={activeTab}
            openEditModal={openEditModal}
            openDeleteModal={openDeleteModal}
            openAddModal={openAddModal}
            openCopyModal={openCopyModal}
            copyingId={eventToCopy?.id}
          />
        </div>

        {/* RIGHT COLUMN: Sidebar (Details & Highlights) */}
        <Sidebar 
          selectedDate={selectedDate}
          currentDate={currentDate}
          selectedEvents={selectedEvents}
          activeEventsList={activeEventsList}
          activeTab={activeTab}
          openAddModal={() => openAddModal()}
          openEditModal={openEditModal}
          openDeleteModal={openDeleteModal}
          openCopyModal={openCopyModal}
          setIsAIModalOpen={setIsAIModalOpen}
          copyingId={eventToCopy?.id}
        />

      </div>
      </div>
    </div>
  );
}

import React from 'react';
import { X, Loader2, AlertCircle, CalendarPlus, Sparkles } from 'lucide-react';
import { SchoolEvent } from '../types';
import { CATEGORY_LABELS } from '../constants';
import { formatEventDateRange } from '../utils';

// --- ADD / EDIT MODAL ---
interface AddEditModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (e: React.FormEvent) => void;
  formData: { title: string; category: string; start: string; end: string };
  setFormData: (data: any) => void;
  isSubmitting: boolean;
  editingEvent: SchoolEvent | null;
  activeTab: 'draft' | 'public';
}

export const AddEditModal = ({ isOpen, onClose, onSubmit, formData, setFormData, isSubmitting, editingEvent, activeTab }: AddEditModalProps) => {
  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={onClose}></div>
      <div className="bg-white rounded-xl shadow-xl w-full max-w-md relative z-10 overflow-hidden">
        <div className={`p-4 border-b border-gray-100 flex justify-between items-center ${activeTab === 'public' ? 'bg-emerald-50' : 'bg-gray-50'}`}>
          <div className="flex flex-col">
              <h3 className="font-semibold text-lg">{editingEvent ? 'Kemaskini Aktiviti' : 'Tambah Aktiviti Baru'}</h3>
              <span className="text-xs text-gray-500">{activeTab === 'public' ? 'Takwim Rasmi (Google Calendar)' : 'Draf Dalaman'}</span>
          </div>
          <button onClick={onClose} className="p-1 hover:bg-gray-200 rounded-full transition"><X size={20}/></button>
        </div>
        <form onSubmit={onSubmit} className="p-6 space-y-4">
            <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Tarikh Mula</label>
                  <input 
                    type="date" 
                    required
                    value={formData.start}
                    onChange={e => setFormData({...formData, start: e.target.value})}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Tarikh Tamat</label>
                  <input 
                    type="date" 
                    value={formData.end}
                    onChange={e => setFormData({...formData, end: e.target.value})}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition"
                  />
                </div>
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Tajuk Aktiviti</label>
              <input 
                type="text" 
                required
                placeholder="Contoh: Mesyuarat Guru"
                value={formData.title}
                onChange={e => setFormData({...formData, title: e.target.value})}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Kategori</label>
              <select 
                value={formData.category}
                onChange={e => setFormData({...formData, category: e.target.value})}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition"
              >
                {Object.keys(CATEGORY_LABELS).map(key => (
                  <option key={key} value={key}>{CATEGORY_LABELS[key]}</option>
                ))}
              </select>
              {activeTab === 'public' && <p className="text-xs text-amber-600 mt-1">Nota: Kategori dalam Google Calendar ditentukan secara automatik berdasarkan kata kunci tajuk.</p>}
            </div>
            <div className="pt-2 flex justify-end gap-2">
              <button type="button" onClick={onClose} className="px-4 py-2 text-gray-600 font-medium hover:bg-gray-100 rounded-lg transition">Batal</button>
              <button 
              type="submit" 
              disabled={isSubmitting}
              className={`px-4 py-2 text-white font-medium rounded-lg transition flex items-center gap-2 disabled:opacity-70 ${activeTab === 'public' ? 'bg-emerald-600 hover:bg-emerald-700' : 'bg-blue-600 hover:bg-blue-700'}`}
              >
                {isSubmitting && <Loader2 className="w-4 h-4 animate-spin"/>}
                {editingEvent ? 'Simpan' : 'Tambah'}
              </button>
            </div>
        </form>
      </div>
    </div>
  );
};

// --- DELETE MODAL ---
interface DeleteModalProps {
  isOpen: boolean;
  onClose: () => void;
  onConfirm: () => void;
  isSubmitting: boolean;
  activeTab: 'draft' | 'public';
}

export const DeleteModal = ({ isOpen, onClose, onConfirm, isSubmitting, activeTab }: DeleteModalProps) => {
  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={onClose}></div>
      <div className="bg-white rounded-xl shadow-xl w-full max-w-sm relative z-10 overflow-hidden transform transition-all scale-100">
        <div className="p-6 flex flex-col items-center text-center">
          <div className="w-12 h-12 bg-red-100 rounded-full flex items-center justify-center mb-4">
            <AlertCircle className="w-6 h-6 text-red-600" />
          </div>
          <h3 className="text-lg font-bold text-gray-900 mb-2">Padam Aktiviti?</h3>
          <p className="text-sm text-gray-500 mb-6">
            Adakah anda pasti mahu memadam aktiviti ini? Tindakan ini tidak boleh dikembalikan.
            {activeTab === 'public' && <span className="block mt-1 font-bold text-red-600">Amaran: Ini akan memadam dari Google Calendar rasmi.</span>}
          </p>
          <div className="flex gap-3 w-full">
            <button 
              onClick={onClose}
              className="flex-1 px-4 py-2 bg-gray-100 hover:bg-gray-200 text-gray-700 font-medium rounded-lg transition"
            >
              Batal
            </button>
            <button 
              onClick={onConfirm}
              disabled={isSubmitting}
              className="flex-1 px-4 py-2 bg-red-600 hover:bg-red-700 text-white font-medium rounded-lg transition flex items-center justify-center gap-2"
            >
              {isSubmitting ? <Loader2 className="w-4 h-4 animate-spin"/> : "Padam"}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

// --- COPY MODAL ---
interface CopyModalProps {
  isOpen: boolean;
  onClose: () => void;
  onConfirm: () => void;
  isSubmitting: boolean;
  eventToCopy: SchoolEvent | null;
}

export const CopyModal = ({ isOpen, onClose, onConfirm, isSubmitting, eventToCopy }: CopyModalProps) => {
  if (!isOpen || !eventToCopy) return null;

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={onClose}></div>
      <div className="bg-white rounded-xl shadow-xl w-full max-w-sm relative z-10 overflow-hidden transform transition-all scale-100">
        <div className="bg-emerald-600 p-4 flex justify-center">
            <CalendarPlus className="w-10 h-10 text-white" />
        </div>
        <div className="p-6 flex flex-col items-center text-center">
          <h3 className="text-lg font-bold text-gray-900 mb-2">Tambah ke Takwim Rasmi?</h3>
          <div className="mb-6 bg-gray-50 p-3 rounded-lg w-full text-left border border-gray-100">
              <p className="font-semibold text-gray-800">{eventToCopy.title}</p>
              <p className="text-sm text-gray-500">{formatEventDateRange(eventToCopy)}</p>
          </div>
          <p className="text-xs text-gray-500 mb-6">
            Tindakan ini akan menyalin acara dari Draf ke <strong>Google Calendar Rasmi</strong>. Orang awam akan dapat melihat acara ini serta-merta.
          </p>

          <div className="flex gap-3 w-full">
            <button 
              onClick={onClose}
              className="flex-1 px-4 py-2 bg-gray-100 hover:bg-gray-200 text-gray-700 font-medium rounded-lg transition"
            >
              Batal
            </button>
            <button 
              onClick={onConfirm}
              disabled={isSubmitting}
              className="flex-1 px-4 py-2 bg-emerald-600 hover:bg-emerald-700 text-white font-medium rounded-lg transition flex items-center justify-center gap-2"
            >
              {isSubmitting ? <Loader2 className="w-4 h-4 animate-spin"/> : "Ya, Tambah"}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

// --- AI MODAL ---
interface AIModalProps {
  isOpen: boolean;
  onClose: () => void;
  activeTab: 'draft' | 'public';
  aiInputText: string;
  setAiInputText: (text: string) => void;
  isProcessingAI: boolean;
  handleAIProcess: () => void;
  aiCategory: string;
  setAiCategory: (cat: string) => void;
}

export const AIModal = ({ isOpen, onClose, activeTab, aiInputText, setAiInputText, isProcessingAI, handleAIProcess, aiCategory, setAiCategory }: AIModalProps) => {
  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-black/40 backdrop-blur-sm" onClick={onClose}></div>
      <div className="bg-white rounded-xl shadow-xl w-full max-w-lg relative z-10 overflow-hidden">
          <div className="bg-gradient-to-r from-purple-600 to-indigo-600 p-4 text-white flex justify-between items-center">
            <div className="flex items-center gap-2">
                <Sparkles className="w-5 h-5 text-yellow-300" />
                <h3 className="font-semibold text-lg">AI Bulk Import ({activeTab === 'draft' ? 'Draf' : 'Rasmi'})</h3>
            </div>
            <button onClick={onClose} className="p-1 hover:bg-white/20 rounded-full transition"><X size={20}/></button>
          </div>

          <div className="p-6">
            <p className="text-sm text-gray-600 mb-4">
              Tampal teks jadual anda di sini. AI akan mengekstrak Tarikh, Tajuk dan Kategori.
            </p>

             <div className="mb-3">
                <label className="block text-xs font-medium text-gray-700 mb-1">Kategori Acara (Untuk Semua Item)</label>
                <select 
                    value={aiCategory}
                    onChange={(e) => setAiCategory(e.target.value)}
                    className="w-full p-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-purple-500 focus:border-purple-500 outline-none transition"
                >
                    <option value="auto">✨ Auto (AI Tentukan)</option>
                    {Object.entries(CATEGORY_LABELS).map(([key, label]) => (
                        <option key={key} value={key}>{label}</option>
                    ))}
                </select>
                {aiCategory !== 'auto' && (
                    <p className="text-[10px] text-purple-600 mt-1">Semua acara yang diekstrak akan ditetapkan sebagai <b>{CATEGORY_LABELS[aiCategory]}</b>.</p>
                )}
            </div>

            <textarea 
              value={aiInputText}
              onChange={(e) => setAiInputText(e.target.value)}
              placeholder="Contoh: Mesyuarat PIBG pada 27/02/2026. Latihan Sukan setiap Rabu."
              className="w-full h-32 p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-purple-500 outline-none resize-none text-sm mb-4"
            ></textarea>

            <div className="flex justify-end gap-2">
                <button 
                  onClick={onClose}
                  className="px-4 py-2 text-gray-600 hover:bg-gray-100 rounded-lg transition"
                >
                  Batal
                </button>
                <button 
                  onClick={handleAIProcess}
                  disabled={!aiInputText.trim() || isProcessingAI}
                  className="px-4 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 transition flex items-center gap-2 disabled:opacity-50"
                >
                  <Sparkles size={16} />
                  Proses dengan AI
                </button>
            </div>
          </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Loader2, Sparkles } from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";

import Header from './components/Header';
import CalendarSection from './components/CalendarSection';
import Sidebar from './components/Sidebar';
import EventListSection from './components/EventListSection';
import { AddEditModal, DeleteModal, CopyModal, AIModal } from './components/Modals';

import { SchoolEvent } from './types';
import { API_URL, SCHOOL_DATA } from './constants';
import { formatDate, getEventsForDate } from './utils';

export default function App() {
  const getInitialDate = () => {
    const today = new Date();
    // Default to 2026 for this specific calendar app
    return new Date(2026, today.getMonth(), today.getDate());
  };

  const [activeTab, setActiveTab] = useState<'draft' | 'public'>('draft');
  const [currentDate, setCurrentDate] = useState<Date>(getInitialDate()); 
  const [selectedDate, setSelectedDate] = useState<Date>(getInitialDate());

  const [draftEvents, setDraftEvents] = useState<SchoolEvent[]>([]);
  const [publicEvents, setPublicEvents] = useState<SchoolEvent[]>([]);

  const [loading, setLoading] = useState(true);

  // Modal State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [eventToDeleteId, setEventToDeleteId] = useState<string | null>(null);

  // AI Modal State
  const [isAIModalOpen, setIsAIModalOpen] = useState(false);
  const [aiInputText, setAiInputText] = useState("");
  const [aiCategory, setAiCategory] = useState("auto");
  const [isProcessingAI, setIsProcessingAI] = useState(false);

  // Copy Modal State
  const [isCopyModalOpen, setIsCopyModalOpen] = useState(false);
  const [eventToCopy, setEventToCopy] = useState<SchoolEvent | null>(null);

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [editingEvent, setEditingEvent] = useState<SchoolEvent | null>(null);
  const [formData, setFormData] = useState({ title: '', category: 'academic', start: '', end: '' });

  // --- API FUNCTIONS ---

  const fetchDraftEvents = async () => {
    setLoading(true);
    try {
      const response = await fetch(API_URL);
      const result = await response.json();
      if (result.status === 'success') {
        setDraftEvents(result.data);
      } else {
        console.error("Failed to fetch draft:", result.message);
      }
    } catch (error) {
      console.error("Error fetching draft events:", error);
    } finally {
      setLoading(false);
    }
  };

  const fetchPublicEvents = async () => {
    setLoading(true);
    try {
        const response = await fetch(`${API_URL}?source=gcal`);
        const result = await response.json();

        if (result.status === 'success') {
            setPublicEvents(result.data);
        } else {
            console.warn("GCal fetch warning:", result.message);
            setPublicEvents([]);
        }
    } catch (error) {
        console.error("Error fetching public GCal events:", error);
    } finally {
        setLoading(false);
    }
  };

  const saveEvent = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);

    if (formData.end && formData.start && formData.end < formData.start) {
        alert("Tarikh tamat tidak boleh sebelum tarikh mula.");
        setIsSubmitting(false);
        return;
    }

    try {
      const action = editingEvent ? 'update' : 'create';
      const payload = {
        action,
        source: activeTab === 'public' ? 'gcal' : 'draft',
        id: editingEvent ? editingEvent.id : undefined,
        title: formData.title,
        category: formData.category,
        start: formData.start,
        end: formData.end || formData.start
      };

      await fetch(API_URL, {
        method: 'POST',
        body: JSON.stringify(payload),
      });

      if (activeTab === 'public') {
          await fetchPublicEvents();
      } else {
          await fetchDraftEvents();
      }
      closeModal();
    } catch (error) {
      console.error("Error saving:", error);
      alert("Ralat menyimpan data. Sila cuba lagi.");
    } finally {
      setIsSubmitting(false);
    }
  };

  // Trigger modal delete
  const openDeleteModal = (id: string) => {
    setEventToDeleteId(id);
    setIsDeleteModalOpen(true);
  };

  const confirmDelete = async () => {
    if(!eventToDeleteId) return;

    setIsSubmitting(true); 
    try {
      await fetch(API_URL, {
        method: 'POST',
        body: JSON.stringify({ 
            action: 'delete', 
            id: eventToDeleteId,
            source: activeTab === 'public' ? 'gcal' : 'draft' 
        }),
      });

      if (activeTab === 'public') {
          await fetchPublicEvents();
      } else {
          await fetchDraftEvents();
      }
      setIsDeleteModalOpen(false);
      setEventToDeleteId(null);
    } catch (error) {
      console.error("Error deleting:", error);
      alert("Ralat memadam data.");
    } finally {
      setIsSubmitting(false);
    }
  };

  // --- COPY TO GCAL LOGIC ---
  const openCopyModal = (evt: SchoolEvent) => {
      setEventToCopy(evt);
      setIsCopyModalOpen(true);
  };

  const confirmCopy = async () => {
    if (!eventToCopy || !eventToCopy.id) return;
    setIsSubmitting(true);

    try {
        await fetch(API_URL, {
            method: 'POST',
            body: JSON.stringify({
                action: 'copy_to_gcal',
                id: eventToCopy.id
            }),
        });

        await fetchPublicEvents();
        setIsCopyModalOpen(false);
        setEventToCopy(null);
        alert(`"${eventToCopy.title}" berjaya ditambah ke Takwim Rasmi (Google Calendar).`);
    } catch (error) {
        console.error("Error copying to GCal:", error);
        alert("Gagal menyalin ke Google Calendar.");
    } finally {
        setIsSubmitting(false);
    }
  };

  // --- AI LOGIC ---
  const openAIModal = (category: string = "auto") => {
      setAiCategory(category === 'all' ? 'auto' : category);
      setAiInputText("");
      setIsAIModalOpen(true);
  };

  const handleAIProcess = async () => {
    if (!aiInputText.trim()) return;
    setIsProcessingAI(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `
        Anda adalah pembantu takwim sekolah. Ekstrak senarai acara dari teks yang diberikan ke dalam format JSON.

        Kategori yang dibenarkan:
        - academic (untuk persekolahan, kelas, bengkel)
        - holiday (cuti, pelepasan)
        - exam (peperiksaan, ujian)
        - program (program sekolah, sambutan)
        - hem (hal ehwal murid, asrama, disiplin)
        - koko (sukan, kelab, persatuan)
        - meeting (mesyuarat)

        Jika kategori tidak jelas, gunakan 'program'.
        Tarikh mesti dalam format YYYY-MM-DD. Jika tiada tarikh tamat, gunakan tarikh mula sebagai tarikh tamat.
        Tahun semasa adalah 2026.

        Teks Input:
        "${aiInputText}"
      `;

      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash",
        contents: prompt,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                title: { type: Type.STRING },
                start: { type: Type.STRING },
                end: { type: Type.STRING },
                category: { type: Type.STRING }
              },
              required: ["title", "start", "category"]
            }
          }
        }
      });

      const parsedEvents = JSON.parse(response.text);

      // Apply forced category if selected
      const extractedEvents = parsedEvents.map((evt: any) => ({
          ...evt,
          category: aiCategory !== 'auto' ? aiCategory : (evt.category || 'program')
      }));

      if (extractedEvents.length > 0) {
        const apiResponse = await fetch(API_URL, {
          method: 'POST',
          body: JSON.stringify({ 
              action: 'bulk_create', 
              events: extractedEvents,
              source: activeTab === 'public' ? 'gcal' : 'draft'
          }),
        });

        const result = await apiResponse.json();

        if (result.status === 'success') {
          alert(`Proses Selesai!\n${result.added} acara ditambah.\n${result.duplicates} acara diabaikan (duplikasi).`);
          if (activeTab === 'public') await fetchPublicEvents();
          else await fetchDraftEvents();

          setAiInputText("");
          setIsAIModalOpen(false);
        } else {
          alert("Ralat menyimpan data ke pangkalan data.");
        }
      } else {
        alert("Tiada acara dapat diekstrak dari teks tersebut.");
      }

    } catch (error) {
      console.error("AI Processing Error:", error);
      alert("Berlaku ralat semasa memproses AI. Sila cuba lagi.");
    } finally {
      setIsProcessingAI(false);
    }
  };

  useEffect(() => {
    fetchDraftEvents();
    fetchPublicEvents();
  }, []);

  const [selectedEvents, setSelectedEvents] = useState<SchoolEvent[]>([]);

  // Navigation Logic
  const nextMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));
  const prevMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));

  // Modals Open Logic
  const openAddModal = (preselectedCategory?: string) => {
    setEditingEvent(null);
    const dateStr = formatDate(selectedDate);
    setFormData({
      title: '',
      category: preselectedCategory || 'program',
      start: dateStr,
      end: dateStr
    });
    setIsModalOpen(true);
  };

  const openEditModal = (evt: SchoolEvent) => {
    setEditingEvent(evt);
    setFormData({
      title: evt.title,
      category: evt.category,
      start: evt.start || '',
      end: evt.end || evt.start || ''
    });
    setIsModalOpen(true);
  };

  const closeModal = () => {
    setIsModalOpen(false);
    setEditingEvent(null);
  };

  const activeEventsList = activeTab === 'draft' ? draftEvents : publicEvents;

  useEffect(() => {
    const evts = getEventsForDate(selectedDate, activeEventsList, SCHOOL_DATA.terms);
    setSelectedEvents(evts);
  }, [selectedDate, draftEvents, publicEvents, activeTab]);

  return (
    <div className="min-h-screen bg-gray-100 font-sans text-slate-800">

      <Header activeTab={activeTab} setActiveTab={setActiveTab} />

      <div className="pt-20 p-4">

      {/* Loading Overlay */}
      {loading && activeEventsList.length === 0 && (
         <div className="fixed inset-0 bg-white/80 z-50 flex items-center justify-center">
            <div className="flex flex-col items-center gap-3">
               <Loader2 className="w-8 h-8 animate-spin text-blue-600" />
               <p className="text-sm font-medium text-gray-600">Sedang memuat data...</p>
            </div>
         </div>
      )}

      {/* AI Processing Overlay */}
      {isProcessingAI && (
         <div className="fixed inset-0 bg-white/90 z-[70] flex items-center justify-center">
            <div className="flex flex-col items-center gap-4 animate-pulse">
               <Sparkles className="w-12 h-12 text-purple-600 animate-spin" />
               <div className="text-center">
                  <p className="text-lg font-bold text-gray-800">Sedang Memproses...</p>
                  <p className="text-sm text-gray-500">AI sedang membaca jadual anda dan menyimpannya.</p>
               </div>
            </div>
         </div>
      )}

      {/* MODALS */}
      <AIModal 
        isOpen={isAIModalOpen} 
        onClose={() => setIsAIModalOpen(false)} 
        activeTab={activeTab}
        aiInputText={aiInputText}
        setAiInputText={setAiInputText}
        isProcessingAI={isProcessingAI}
        handleAIProcess={handleAIProcess}
        aiCategory={aiCategory}
        setAiCategory={setAiCategory}
      />

      <AddEditModal 
        isOpen={isModalOpen} 
        onClose={closeModal} 
        onSubmit={saveEvent}
        formData={formData}
        setFormData={setFormData}
        isSubmitting={isSubmitting}
        editingEvent={editingEvent}
        activeTab={activeTab}
      />

      <DeleteModal 
        isOpen={isDeleteModalOpen} 
        onClose={() => setIsDeleteModalOpen(false)} 
        onConfirm={confirmDelete}
        isSubmitting={isSubmitting}
        activeTab={activeTab}
      />

      <CopyModal 
        isOpen={isCopyModalOpen} 
        onClose={() => setIsCopyModalOpen(false)} 
        onConfirm={confirmCopy}
        isSubmitting={isSubmitting}
        eventToCopy={eventToCopy}
      />

      <div className="max-w-7xl mx-auto grid grid-cols-1 lg:grid-cols-3 gap-6">

        {/* LEFT COLUMN: Calendar & Navigation */}
        <div className="lg:col-span-2 space-y-6">
          <CalendarSection 
            currentDate={currentDate}
            selectedDate={selectedDate}
            setSelectedDate={setSelectedDate}
            activeTab={activeTab}
            prevMonth={prevMonth}
            nextMonth={nextMonth}
            activeEventsList={activeEventsList}
            terms={SCHOOL_DATA.terms}
            loading={loading}
          />

          <EventListSection 
            events={activeEventsList}
            activeTab={activeTab}
            openEditModal={openEditModal}
            openDeleteModal={openDeleteModal}
            openAddModal={openAddModal}
            openCopyModal={openCopyModal}
            copyingId={eventToCopy?.id}
            openAIModal={openAIModal}
          />
        </div>

        {/* RIGHT COLUMN: Sidebar (Details & Highlights) */}
        <Sidebar 
          selectedDate={selectedDate}
          currentDate={currentDate}
          selectedEvents={selectedEvents}
          activeEventsList={activeEventsList}
          activeTab={activeTab}
          openAddModal={() => openAddModal()}
          openEditModal={openEditModal}
          openDeleteModal={openDeleteModal}
          openCopyModal={openCopyModal}
          openAIModal={openAIModal}
          copyingId={eventToCopy?.id}
        />

      </div>
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { Edit, Trash2, Plus, Calendar, Filter, CalendarPlus, Loader2, Sparkles } from 'lucide-react';
import { SchoolEvent } from '../types';
import { CATEGORY_LABELS, CATEGORY_STYLES } from '../constants';
import { formatEventDateRange, getCategoryIcon } from '../utils';

interface EventListSectionProps {
  events: SchoolEvent[];
  activeTab: 'draft' | 'public';
  openEditModal: (evt: SchoolEvent) => void;
  openDeleteModal: (id: string) => void;
  openAddModal: (category?: string) => void;
  openCopyModal: (evt: SchoolEvent) => void;
  copyingId?: string | null;
  openAIModal: (category?: string) => void;
}

const TABS = [
  { key: 'all', label: 'Semua' },
  { key: 'holiday', label: 'Cuti' },
  { key: 'academic', label: 'Sekolah' },
  { key: 'exam', label: 'Peperiksaan' },
  { key: 'program', label: 'Program' },
  { key: 'hem', label: 'HEM' },
  { key: 'koko', label: 'Kokurikulum' },
  { key: 'meeting', label: 'Mesyuarat' },
];

export default function EventListSection({
  events,
  activeTab,
  openEditModal,
  openDeleteModal,
  openAddModal,
  openCopyModal,
  copyingId,
  openAIModal
}: EventListSectionProps) {
  const [activeCategory, setActiveCategory] = useState('all');

  // Filter and Sort Events
  const filteredEvents = events
    .filter(evt => activeCategory === 'all' || evt.category === activeCategory)
    .sort((a, b) => {
        if (!a.start || !b.start) return 0;
        return new Date(a.start).getTime() - new Date(b.start).getTime();
    });

  return (
    <div className="bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden">
      <div className="p-6 border-b border-gray-100 flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
            <h3 className="text-lg font-bold text-gray-800 flex items-center gap-2">
                <Filter size={20} className="text-blue-600" />
                Senarai Pengurusan Takwim
            </h3>
            <p className="text-sm text-gray-500">Urus semua acara sekolah mengikut kategori.</p>
        </div>

        <div className="flex gap-2 items-center">
            <button 
                onClick={() => openAIModal(activeCategory)}
                className="flex items-center gap-2 bg-purple-600 hover:bg-purple-700 text-white px-4 py-2 rounded-lg text-sm font-medium transition shadow-sm w-fit"
            >
                <Sparkles size={16} />
                AI Import
            </button>
            <button 
                onClick={() => openAddModal(activeCategory === 'all' ? 'program' : activeCategory)}
                className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg text-sm font-medium transition shadow-sm w-fit"
            >
                <Plus size={16} />
                Tambah {activeCategory !== 'all' ? CATEGORY_LABELS[activeCategory] : 'Acara'}
            </button>
        </div>
      </div>

      {/* Tabs */}
      <div className="border-b border-gray-100 overflow-x-auto">
        <div className="flex px-4 min-w-max">
            {TABS.map((tab) => (
                <button
                    key={tab.key}
                    onClick={() => setActiveCategory(tab.key)}
                    className={`px-4 py-3 text-sm font-medium border-b-2 transition-colors duration-200 ${
                        activeCategory === tab.key 
                        ? 'border-blue-600 text-blue-600' 
                        : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                    }`}
                >
                    {tab.label}
                </button>
            ))}
        </div>
      </div>

      {/* Event List */}
      <div className="bg-gray-50 min-h-[300px] max-h-[600px] overflow-y-auto p-4 custom-scrollbar">
        {filteredEvents.length > 0 ? (
            <div className="space-y-3">
                {filteredEvents.map((evt, idx) => (
                    <div 
                        key={evt.id || idx} 
                        className="bg-white p-4 rounded-xl shadow-sm border border-gray-100 flex flex-col sm:flex-row gap-4 items-start sm:items-center hover:shadow-md transition-shadow group"
                    >
                        {/* Date Box */}
                        <div className="flex sm:flex-col items-center justify-center bg-gray-100 rounded-lg p-2 min-w-[4rem] sm:min-w-[5rem] text-center shrink-0 gap-2 sm:gap-0">
                             <span className="text-xs font-bold text-gray-500 uppercase">
                                {evt.start ? new Date(evt.start).toLocaleString('ms-MY', { month: 'short' }) : '-'}
                             </span>
                             <span className="text-xl sm:text-2xl font-bold text-gray-800 leading-none">
                                {evt.start ? new Date(evt.start).getDate() : '-'}
                             </span>
                        </div>

                        {/* Content */}
                        <div className="flex-1 min-w-0">
                            <div className="flex items-center gap-2 mb-1">
                                <span className={`text-[10px] px-2 py-0.5 rounded-full font-medium border ${CATEGORY_STYLES[evt.category]?.replace('bg-', 'bg-opacity-20 ')}`}>
                                    {CATEGORY_LABELS[evt.category]}
                                </span>
                            </div>
                            <h4 className="font-semibold text-gray-800 text-sm sm:text-base mb-1">{evt.title}</h4>
                            <div className="flex items-center gap-4 text-xs text-gray-500">
                                <span className="flex items-center gap-1">
                                    <Calendar size={12} />
                                    {formatEventDateRange(evt)}
                                </span>
                            </div>
                        </div>

                        {/* Actions */}
                        <div className="flex items-center gap-2 w-full sm:w-auto justify-end border-t sm:border-t-0 pt-3 sm:pt-0 mt-2 sm:mt-0 border-gray-100">
                            {/* Butang Tambah ke Takwim Rasmi (Hanya untuk Draf) */}
                            {activeTab === 'draft' && (
                                <button 
                                    onClick={() => openCopyModal(evt)}
                                    className="p-2 text-emerald-600 bg-emerald-50 hover:bg-emerald-100 rounded-lg transition border border-emerald-100"
                                    title="Tambah ke Takwim Rasmi"
                                    disabled={copyingId === evt.id}
                                >
                                    {copyingId === evt.id ? <Loader2 size={16} className="animate-spin" /> : <CalendarPlus size={16} />}
                                </button>
                            )}

                            <button 
                                onClick={() => openEditModal(evt)}
                                className="p-2 text-blue-600 bg-blue-50 hover:bg-blue-100 rounded-lg transition"
                                title="Edit"
                            >
                                <Edit size={16} />
                            </button>
                            <button 
                                onClick={() => evt.id && openDeleteModal(evt.id)}
                                className="p-2 text-red-600 bg-red-50 hover:bg-red-100 rounded-lg transition"
                                title="Padam"
                            >
                                <Trash2 size={16} />
                            </button>
                        </div>
                    </div>
                ))}
            </div>
        ) : (
            <div className="flex flex-col items-center justify-center h-64 text-gray-400">
                <Calendar size={48} className="mb-4 opacity-20" />
                <p>Tiada acara dalam kategori ini.</p>
                <div className="flex gap-3">
                    <button 
                        onClick={() => openAIModal(activeCategory)}
                        className="mt-2 text-purple-600 text-sm font-medium hover:underline flex items-center gap-1"
                    >
                        <Sparkles size={14}/>
                        AI Import
                    </button>
                    <button 
                        onClick={() => openAddModal(activeCategory === 'all' ? 'program' : activeCategory)}
                        className="mt-2 text-blue-600 text-sm font-medium hover:underline flex items-center gap-1"
                    >
                        <Plus size={14}/>
                        Tambah Acara
                    </button>
                </div>
            </div>
        )}
      </div>
    </div>
  );
}

import React from 'react';
import { Activity, Plus, Sparkles, Calendar, Edit, Trash2, CalendarPlus, ArrowRight, Loader2 } from 'lucide-react';
import { SchoolEvent } from '../types';
import { MONTH_NAMES, CATEGORY_STYLES, CATEGORY_LABELS } from '../constants';
import { getCategoryIcon, formatEventDateRange } from '../utils';

interface SidebarProps {
  selectedDate: Date;
  currentDate: Date;
  selectedEvents: SchoolEvent[];
  activeEventsList: SchoolEvent[];
  activeTab: 'draft' | 'public';
  openAddModal: () => void;
  openEditModal: (evt: SchoolEvent) => void;
  openDeleteModal: (id: string) => void;
  openCopyModal: (evt: SchoolEvent) => void;
  openAIModal: (category?: string) => void;
  copyingId?: string | null;
}

export default function Sidebar({
  selectedDate,
  currentDate,
  selectedEvents,
  activeEventsList,
  activeTab,
  openAddModal,
  openEditModal,
  openDeleteModal,
  openCopyModal,
  openAIModal,
  copyingId
}: SidebarProps) {

  const dayName = ['Ahad', 'Isnin', 'Selasa', 'Rabu', 'Khamis', 'Jumaat', 'Sabtu'][selectedDate.getDay()];

  return (
    <div className="space-y-6">

      {/* Selected Date Details */}
      <div className="bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden">
          <div className="bg-slate-800 text-white p-6 relative">
            <h2 className="text-3xl font-bold">{selectedDate.getDate()}</h2>
            <h3 className="text-xl opacity-90">{MONTH_NAMES[selectedDate.getMonth()]} {selectedDate.getFullYear()}</h3>
            <p className="opacity-75 mt-1">{dayName}</p>

            <div className="absolute right-6 top-6 flex gap-2">
            <button 
                onClick={() => openAIModal()}
                className="bg-purple-600 hover:bg-purple-500 text-white p-2 rounded-full shadow-lg transition-transform hover:scale-105 active:scale-95" 
                title="AI Bulk Import"
            >
                <Sparkles size={20} />
            </button>
            <button 
                onClick={openAddModal}
                className={`${activeTab === 'public' ? 'bg-emerald-600 hover:bg-emerald-500' : 'bg-blue-600 hover:bg-blue-500'} text-white p-2 rounded-full shadow-lg transition-transform hover:scale-105 active:scale-95`}
                title="Tambah Aktiviti"
            >
                <Plus size={20} />
            </button>
            </div>
          </div>

          <div className="p-6">
            <h4 className="font-semibold text-gray-700 mb-4 flex items-center gap-2">
              <Activity size={18} />
              Aktiviti Hari Ini
            </h4>

            {selectedEvents.length > 0 ? (
              <div className="space-y-3">
                {selectedEvents.map((evt, idx) => (
                  <div key={idx} className={`p-3 rounded-lg border-l-4 text-sm ${CATEGORY_STYLES[evt.category] || CATEGORY_STYLES.default} border-l-[color:inherit] bg-opacity-30 group relative`}>
                    <div className="flex items-start gap-2 pr-12">
                      <span className="mt-0.5 opacity-70">{getCategoryIcon(evt.category)}</span>
                      <div>
                        <div className="font-medium">{evt.title}</div>

                        {evt.start && evt.end && evt.start !== evt.end && (
                            <div className="text-[10px] text-gray-600 mt-1 font-mono flex items-center gap-1">
                                <Calendar size={10} />
                                {formatEventDateRange(evt)}
                            </div>
                        )}

                        <div className="text-xs opacity-75 mt-1 uppercase tracking-wider">{CATEGORY_LABELS[evt.category] || "Umum"}</div>
                      </div>
                    </div>

                    {evt.id && (
                      <div className="absolute right-2 top-2 flex gap-1 opacity-100 sm:opacity-0 group-hover:opacity-100 transition-opacity">
                          {activeTab === 'draft' && (
                            <button 
                                onClick={() => openCopyModal(evt)} 
                                className="p-1.5 bg-white text-emerald-600 rounded shadow hover:bg-gray-50" 
                                title="Salin ke Takwim Rasmi"
                            >
                                <CalendarPlus size={14} />
                            </button>
                          )}

                          <button onClick={() => openEditModal(evt)} className="p-1.5 bg-white text-blue-600 rounded shadow hover:bg-gray-50" title="Edit">
                            <Edit size={14} />
                          </button>
                          <button onClick={() => openDeleteModal(evt.id!)} className="p-1.5 bg-white text-red-600 rounded shadow hover:bg-gray-50" title="Padam">
                            <Trash2 size={14} />
                          </button>
                      </div>
                    )}
                  </div>
                ))}
              </div>
            ) : (
              <div className="text-center py-8 text-gray-400">
                <p>Tiada aktiviti khusus direkodkan.</p>
                <button onClick={openAddModal} className={`mt-4 text-sm font-medium hover:underline ${activeTab === 'public' ? 'text-emerald-600' : 'text-blue-600'}`}>Tambah Aktiviti +</button>
              </div>
            )}
          </div>
      </div>

      {/* Quick Stats / Legend / Upcoming */}
      <div className="bg-white rounded-2xl shadow-sm p-6 border border-gray-200">
        <h4 className="font-semibold text-gray-800 mb-4">Sorotan Bulan Ini ({MONTH_NAMES[currentDate.getMonth()]})</h4>
        <div className="space-y-4">
          {activeEventsList
            .filter(e => {
              if (!e.start) return false;
              const d = new Date(e.start);
              return d.getMonth() === currentDate.getMonth() && d.getFullYear() === currentDate.getFullYear();
            })
            .sort((a,b) => {
                if (!a.start || !b.start) return 0;
                return new Date(a.start).getTime() - new Date(b.start).getTime();
            })
            .slice(0, 5) // Show top 5
            .map((evt, i) => (
              <div key={i} className="flex gap-3 items-start group">
                <div className="bg-gray-100 rounded px-2 py-1 text-center min-w-[3rem]">
                  <div className="text-xs font-bold text-gray-500">{evt.start ? new Date(evt.start).getDate() : '-'}</div>
                  <div className="text-[10px] text-gray-400">{evt.start ? MONTH_NAMES[new Date(evt.start).getMonth()].substring(0,3) : '-'}</div>
                </div>
                <div className="flex-1 min-w-0">
                  <div className="text-sm font-medium text-gray-800 leading-tight truncate">{evt.title}</div>
                  <div className="text-xs text-gray-500 mt-1 flex gap-2">
                    <span>{CATEGORY_LABELS[evt.category]}</span>
                    {evt.end && evt.end !== evt.start && <span className="text-gray-400 text-[10px] flex items-center"><ArrowRight size={8} className="mx-0.5"/> {new Date(evt.end).getDate()}</span>}
                  </div>
                </div>

                {evt.id && (
                    <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity ml-auto shrink-0 self-center">
                      {activeTab === 'draft' && (
                          <button 
                            onClick={() => openCopyModal(evt)} 
                            className="p-1.5 text-emerald-600 hover:bg-emerald-50 rounded shadow-sm border border-gray-100 bg-white" 
                            title="Tambah ke Takwim Rasmi (GCal)"
                            disabled={copyingId === evt.id}
                          >
                            {copyingId === evt.id ? <Loader2 size={14} className="animate-spin"/> : <CalendarPlus size={14} />}
                          </button>
                      )}

                      <button onClick={() => openEditModal(evt)} className="p-1.5 text-blue-600 hover:bg-blue-50 rounded shadow-sm border border-gray-100 bg-white" title="Edit">
                        <Edit size={14} />
                      </button>
                      <button onClick={() => openDeleteModal(evt.id!)} className="p-1.5 text-red-600 hover:bg-red-50 rounded shadow-sm border border-gray-100 bg-white" title="Padam">
                        <Trash2 size={14} />
                      </button>
                    </div>
                )}
              </div>
            ))
          }
          {activeEventsList.filter(e => e.start && new Date(e.start).getMonth() === currentDate.getMonth()).length === 0 && (
              <p className="text-sm text-gray-500 italic">Tiada acara utama disenaraikan bulan ini.</p>
          )}
        </div>
      </div>
    </div>
  );
}

import React, { useEffect, useRef } from 'react';
