// --- BULK SYNC MODAL (PROGRESS) ---
interface LogItem {
    type: 'info' | 'success' | 'skip' | 'error';
    message: string;
}

interface BulkSyncModalProps {
    isOpen: boolean;
    onClose: () => void;
    logs: LogItem[];
    isSyncing: boolean;
    total: number;
    progress: number;
}

export const BulkSyncModal = ({ isOpen, onClose, logs, isSyncing, total, progress }: BulkSyncModalProps) => {
    const logsEndRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (logsEndRef.current) {
            logsEndRef.current.scrollIntoView({ behavior: 'smooth' });
        }
    }, [logs]);

    if (!isOpen) return null;

    const percentage = total > 0 ? Math.round((progress / total) * 100) : 0;

    return (
        <div className="fixed inset-0 z-[80] flex items-center justify-center p-4">
            <div className="absolute inset-0 bg-black/50 backdrop-blur-sm"></div>
            <div className="bg-white rounded-xl shadow-2xl w-full max-w-lg relative z-10 overflow-hidden flex flex-col max-h-[80vh]">
                <div className="bg-emerald-600 p-4 text-white flex justify-between items-center shrink-0">
                    <div className="flex items-center gap-2">
                        <CloudUpload className="w-5 h-5" />
                        <h3 className="font-bold text-lg">Sync ke Takwim Rasmi</h3>
                    </div>
                    {!isSyncing && (
                        <button onClick={onClose} className="p-1 hover:bg-white/20 rounded-full transition"><X size={20} /></button>
                    )}
                </div>

                <div className="p-6 flex-1 flex flex-col overflow-hidden">
                    <div className="mb-4 shrink-0">
                        <div className="flex justify-between text-sm font-medium text-gray-700 mb-1">
                            <span>Status Proses</span>
                            <span>{progress} / {total} ({percentage}%)</span>
                        </div>
                        <div className="w-full bg-gray-200 rounded-full h-2.5 overflow-hidden">
                            <div 
                                className="bg-emerald-500 h-2.5 rounded-full transition-all duration-300 ease-out" 
                                style={{ width: `${percentage}%` }}
                            ></div>
                        </div>
                    </div>

                    <div className="flex-1 bg-slate-900 rounded-lg p-4 overflow-y-auto font-mono text-xs border border-slate-700 shadow-inner">
                        <div className="space-y-1.5">
                            {logs.map((log, idx) => (
                                <div key={idx} className={`flex items-start gap-2 ${
                                    log.type === 'success' ? 'text-emerald-400' : 
                                    log.type === 'skip' ? 'text-amber-400' : 
                                    log.type === 'error' ? 'text-red-400' : 'text-slate-300'
                                }`}>
                                    <span className="shrink-0 mt-0.5">
                                        {log.type === 'success' && <CheckCircle size={10} />}
                                        {log.type === 'skip' && <SkipForward size={10} />}
                                        {log.type === 'error' && <X size={10} />}
                                        {log.type === 'info' && <span className="w-2.5 h-2.5 inline-block" />}
                                    </span>
                                    <span>{log.message}</span>
                                </div>
                            ))}
                            {logs.length === 0 && <span className="text-slate-500 italic">Menunggu proses bermula...</span>}
                            <div ref={logsEndRef} />
                        </div>
                    </div>
                </div>

                <div className="p-4 border-t border-gray-100 bg-gray-50 flex justify-end shrink-0">
                     <button 
                        onClick={onClose} 
                        disabled={isSyncing}
                        className={`px-6 py-2 rounded-lg font-medium transition ${
                            isSyncing 
                            ? 'bg-gray-300 text-gray-500 cursor-not-allowed' 
                            : 'bg-emerald-600 text-white hover:bg-emerald-700 shadow-md'
                        }`}
                    >
                        {isSyncing ? 'Sedang Memproses...' : 'Tutup'}
                    </button>
                </div>
            </div>
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { Loader2, Sparkles } from 'lucide-react';
import { GoogleGenAI, Type } from "@google/genai";

import Header from './components/Header';
import CalendarSection from './components/CalendarSection';
import Sidebar from './components/Sidebar';
import EventListSection from './components/EventListSection';
import { AddEditModal, DeleteModal, CopyModal, AIModal, BulkSyncModal, SyncConfirmationModal } from './components/Modals';

import { SchoolEvent } from './types';
import { API_URL, SCHOOL_DATA, CATEGORY_LABELS } from './constants';
import { formatDate, getEventsForDate } from './utils';

interface LogItem {
    type: 'info' | 'success' | 'skip' | 'error';
    message: string;
}

export default function App() {
  const getInitialDate = () => {
    const today = new Date();
    // Default to 2026 for this specific calendar app
    return new Date(2026, today.getMonth(), today.getDate());
  };

  const [activeTab, setActiveTab] = useState<'draft' | 'public'>('draft');
  const [currentDate, setCurrentDate] = useState<Date>(getInitialDate()); 
  const [selectedDate, setSelectedDate] = useState<Date>(getInitialDate());

  const [draftEvents, setDraftEvents] = useState<SchoolEvent[]>([]);
  const [publicEvents, setPublicEvents] = useState<SchoolEvent[]>([]);

  const [loading, setLoading] = useState(true);

  // Modal State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  const [eventToDeleteId, setEventToDeleteId] = useState<string | null>(null);
  const [bulkDeleteIds, setBulkDeleteIds] = useState<string[]>([]);

  // AI Modal State
  const [isAIModalOpen, setIsAIModalOpen] = useState(false);
  const [aiInputText, setAiInputText] = useState("");
  const [aiCategory, setAiCategory] = useState("auto");
  const [isProcessingAI, setIsProcessingAI] = useState(false);

  // Copy Modal State
  const [isCopyModalOpen, setIsCopyModalOpen] = useState(false);
  const [eventToCopy, setEventToCopy] = useState<SchoolEvent | null>(null);

  // Bulk Sync Modal State
  const [isBulkSyncModalOpen, setIsBulkSyncModalOpen] = useState(false);
  const [isSyncConfirmModalOpen, setIsSyncConfirmModalOpen] = useState(false);
  const [syncLogs, setSyncLogs] = useState<LogItem[]>([]);
  const [isSyncing, setIsSyncing] = useState(false);
  const [syncTotal, setSyncTotal] = useState(0);
  const [syncProgress, setSyncProgress] = useState(0);
  const [pendingSyncData, setPendingSyncData] = useState<{ category: string, ids?: string[] } | null>(null);

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [editingEvent, setEditingEvent] = useState<SchoolEvent | null>(null);
  const [formData, setFormData] = useState({ title: '', category: 'academic', start: '', end: '' });

  // --- API FUNCTIONS ---

  const fetchDraftEvents = async () => {
    setLoading(true);
    try {
      const response = await fetch(API_URL);
      const result = await response.json();
      if (result.status === 'success') {
        setDraftEvents(result.data);
      } else {
        console.error("Failed to fetch draft:", result.message);
      }
    } catch (error) {
      console.error("Error fetching draft events:", error);
    } finally {
      setLoading(false);
    }
  };

  const fetchPublicEvents = async () => {
    setLoading(true);
    try {
        const response = await fetch(`${API_URL}?source=gcal`);
        const result = await response.json();

        if (result.status === 'success') {
            setPublicEvents(result.data);
        } else {
            console.warn("GCal fetch warning:", result.message);
            setPublicEvents([]);
        }
    } catch (error) {
        console.error("Error fetching public GCal events:", error);
    } finally {
        setLoading(false);
    }
  };

  const saveEvent = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);

    if (formData.end && formData.start && formData.end < formData.start) {
        alert("Tarikh tamat tidak boleh sebelum tarikh mula.");
        setIsSubmitting(false);
        return;
    }

    try {
      const action = editingEvent ? 'update' : 'create';
      const payload = {
        action,
        source: activeTab === 'public' ? 'gcal' : 'draft',
        id: editingEvent ? editingEvent.id : undefined,
        title: formData.title,
        category: formData.category,
        start: formData.start,
        end: formData.end || formData.start
      };

      await fetch(API_URL, {
        method: 'POST',
        body: JSON.stringify(payload),
      });

      if (activeTab === 'public') {
          await fetchPublicEvents();
      } else {
          await fetchDraftEvents();
      }
      closeModal();
    } catch (error) {
      console.error("Error saving:", error);
      alert("Ralat menyimpan data. Sila cuba lagi.");
    } finally {
      setIsSubmitting(false);
    }
  };

  // Trigger modal delete (Single)
  const openDeleteModal = (id: string) => {
    setEventToDeleteId(id);
    setBulkDeleteIds([]); // Clear bulk
    setIsDeleteModalOpen(true);
  };

  // Trigger modal delete (Bulk)
  const openBulkDeleteModal = (ids: string[]) => {
      setBulkDeleteIds(ids);
      setEventToDeleteId(null); // Clear single
      setIsDeleteModalOpen(true);
  };

  // The actual API call for bulk delete
  const performBulkDelete = async (ids: string[]) => {
      await fetch(API_URL, {
             method: 'POST',
             body: JSON.stringify({
                 action: 'bulk_delete',
                 ids: ids,
                 source: activeTab === 'public' ? 'gcal' : 'draft'
             })
         });
  };

  // The actual API call for single delete
  const performSingleDelete = async (id: string) => {
       await fetch(API_URL, {
        method: 'POST',
        body: JSON.stringify({ 
            action: 'delete', 
            id: id,
            source: activeTab === 'public' ? 'gcal' : 'draft' 
        }),
      });
  };

  const confirmDelete = async () => {
    setIsSubmitting(true); 
    try {
      if (bulkDeleteIds.length > 0) {
          await performBulkDelete(bulkDeleteIds);
      } else if (eventToDeleteId) {
          await performSingleDelete(eventToDeleteId);
      }

      if (activeTab === 'public') {
          await fetchPublicEvents();
      } else {
          await fetchDraftEvents();
      }
      setIsDeleteModalOpen(false);
      setEventToDeleteId(null);
      setBulkDeleteIds([]);
    } catch (error) {
      console.error("Error deleting:", error);
      alert("Ralat memadam data.");
    } finally {
      setIsSubmitting(false);
    }
  };

  // --- COPY TO GCAL LOGIC ---
  const openCopyModal = (evt: SchoolEvent) => {
      setEventToCopy(evt);
      setIsCopyModalOpen(true);
  };

  const confirmCopy = async () => {
    if (!eventToCopy || !eventToCopy.id) return;
    setIsSubmitting(true);

    try {
        await fetch(API_URL, {
            method: 'POST',
            body: JSON.stringify({
                action: 'copy_to_gcal',
                id: eventToCopy.id
            }),
        });

        await fetchPublicEvents();
        setIsCopyModalOpen(false);
        setEventToCopy(null);
        alert(`"${eventToCopy.title}" berjaya ditambah ke Takwim Rasmi (Google Calendar).`);
    } catch (error) {
        console.error("Error copying to GCal:", error);
        alert("Gagal menyalin ke Google Calendar.");
    } finally {
        setIsSubmitting(false);
    }
  };

  // --- BULK SYNC LOGIC ---
  const handleBulkSync = (category: string, specificIds?: string[]) => {
      setPendingSyncData({ category, ids: specificIds });
      setIsSyncConfirmModalOpen(true);
  };

  const runBulkSync = async () => {
    setIsSyncConfirmModalOpen(false);
    setSyncLogs([]);
    setSyncProgress(0);
    setIsSyncing(true);
    setIsBulkSyncModalOpen(true);

    const { category, ids } = pendingSyncData || { category: 'all' };

    const addLog = (item: LogItem) => {
        setSyncLogs(prev => [...prev, item]);
    };

    // 1. Filter events 
    let eventsToSync: SchoolEvent[] = [];
    if (ids && ids.length > 0) {
        // Sync specifically selected IDs
        eventsToSync = draftEvents.filter(e => e.id && ids.includes(e.id));
        addLog({ type: 'info', message: `Memproses ${eventsToSync.length} acara yang dipilih...` });
    } else {
        // Sync by category
        eventsToSync = draftEvents.filter(e => category === 'all' || e.category === category);
        addLog({ type: 'info', message: `Memproses semua acara kategori "${CATEGORY_LABELS[category] || 'Semua'}"...` });
    }

    setSyncTotal(eventsToSync.length);

    if (eventsToSync.length === 0) {
        addLog({ type: 'info', message: 'Tiada acara untuk disinkronkan.' });
        setIsSyncing(false);
        return;
    }

    // 2. Fetch latest Public Events for comparison
    addLog({ type: 'info', message: 'Menyemak data Takwim Rasmi terkini...' });
    let currentPublicEvents = publicEvents;
    try {
         const response = await fetch(`${API_URL}?source=gcal`);
         const result = await response.json();
         if(result.status === 'success') currentPublicEvents = result.data;
    } catch (e) {
        addLog({type: 'error', message: 'Gagal mendapatkan data terkini. Menggunakan cache.'});
    }

    // 3. Loop and Process
    let successCount = 0;
    let skipCount = 0;

    for (let i = 0; i < eventsToSync.length; i++) {
        const evt = eventsToSync[i];
        setSyncProgress(i + 1);

        // Duplicate Check (Simple: Same Title & Start Date)
        const isDuplicate = currentPublicEvents.some(
            p => p.start === evt.start && p.title.toLowerCase().trim() === evt.title.toLowerCase().trim()
        );

        if (isDuplicate) {
            addLog({ type: 'skip', message: `[Langkau] "${evt.title}" (Sudah wujud)` });
            skipCount++;
            continue;
        }

        try {
            // Call API to Copy
            const res = await fetch(API_URL, {
                method: 'POST',
                body: JSON.stringify({
                    action: 'copy_to_gcal',
                    id: evt.id
                }),
            });
            const data = await res.json();

            if (data.status === 'success') {
                addLog({ type: 'success', message: `[Berjaya] "${evt.title}" ditambah.` });
                successCount++;
            } else {
                addLog({ type: 'error', message: `[Gagal] "${evt.title}": ${data.message}` });
            }

            // Small delay to prevent rate limit and allow UI update
            await new Promise(r => setTimeout(r, 500));

        } catch (error) {
             addLog({ type: 'error', message: `[Ralat Rangkaian] "${evt.title}"` });
        }
    }

    addLog({ type: 'info', message: `Proses Selesai! Ditambah: ${successCount}, Dilangkau: ${skipCount}` });
    setIsSyncing(false);

    // Refresh public events if any changes made
    if (successCount > 0) {
        fetchPublicEvents();
    }
  };

  // --- AI LOGIC ---
  const openAIModal = (category: string = "auto") => {
      setAiCategory(category === 'all' ? 'auto' : category);
      setAiInputText("");
      setIsAIModalOpen(true);
  };

  const handleAIProcess = async () => {
    if (!aiInputText.trim()) return;
    setIsProcessingAI(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `
        Anda adalah pembantu takwim sekolah. Ekstrak senarai acara dari teks yang diberikan ke dalam format JSON.

        Kategori yang dibenarkan:
        - academic (untuk persekolahan, kelas, bengkel)
        - holiday (cuti, pelepasan)
        - exam (peperiksaan, ujian)
        - program (program sekolah, sambutan)
        - hem (hal ehwal murid, asrama, disiplin)
        - koko (sukan, kelab, persatuan)
        - meeting (mesyuarat)

        Jika kategori tidak jelas, gunakan 'program'.
        Tarikh mesti dalam format YYYY-MM-DD. Jika tiada tarikh tamat, gunakan tarikh mula sebagai tarikh tamat.
        Tahun semasa adalah 2026.

        Teks Input:
        "${aiInputText}"
      `;

      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash",
        contents: prompt,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                title: { type: Type.STRING },
                start: { type: Type.STRING },
                end: { type: Type.STRING },
                category: { type: Type.STRING }
              },
              required: ["title", "start", "category"]
            }
          }
        }
      });

      const parsedEvents = JSON.parse(response.text);

      // Apply forced category if selected
      const extractedEvents = parsedEvents.map((evt: any) => ({
          ...evt,
          category: aiCategory !== 'auto' ? aiCategory : (evt.category || 'program')
      }));

      if (extractedEvents.length > 0) {
        const apiResponse = await fetch(API_URL, {
          method: 'POST',
          body: JSON.stringify({ 
              action: 'bulk_create', 
              events: extractedEvents,
              source: activeTab === 'public' ? 'gcal' : 'draft'
          }),
        });

        const result = await apiResponse.json();

        if (result.status === 'success') {
          alert(`Proses Selesai!\n${result.added} acara ditambah.\n${result.duplicates} acara diabaikan (duplikasi).`);
          if (activeTab === 'public') await fetchPublicEvents();
          else await fetchDraftEvents();

          setAiInputText("");
          setIsAIModalOpen(false);
        } else {
          alert("Ralat menyimpan data ke pangkalan data.");
        }
      } else {
        alert("Tiada acara dapat diekstrak dari teks tersebut.");
      }

    } catch (error) {
      console.error("AI Processing Error:", error);
      alert("Berlaku ralat semasa memproses AI. Sila cuba lagi.");
    } finally {
      setIsProcessingAI(false);
    }
  };

  useEffect(() => {
    fetchDraftEvents();
    fetchPublicEvents();
  }, []);

  const [selectedEvents, setSelectedEvents] = useState<SchoolEvent[]>([]);

  // Navigation Logic
  const nextMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));
  const prevMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));

  // Modals Open Logic
  const openAddModal = (preselectedCategory?: string) => {
    setEditingEvent(null);
    const dateStr = formatDate(selectedDate);
    setFormData({
      title: '',
      category: preselectedCategory || 'program',
      start: dateStr,
      end: dateStr
    });
    setIsModalOpen(true);
  };

  const openEditModal = (evt: SchoolEvent) => {
    setEditingEvent(evt);
    setFormData({
      title: evt.title,
      category: evt.category,
      start: evt.start || '',
      end: evt.end || evt.start || ''
    });
    setIsModalOpen(true);
  };

  const closeModal = () => {
    setIsModalOpen(false);
    setEditingEvent(null);
  };

  const activeEventsList = activeTab === 'draft' ? draftEvents : publicEvents;

  useEffect(() => {
    const evts = getEventsForDate(selectedDate, activeEventsList, SCHOOL_DATA.terms);
    setSelectedEvents(evts);
  }, [selectedDate, draftEvents, publicEvents, activeTab]);

  return (
    <div className="min-h-screen bg-gray-100 font-sans text-slate-800">

      <Header activeTab={activeTab} setActiveTab={setActiveTab} />

      <div className="pt-20 p-4">

      {/* Loading Overlay */}
      {loading && activeEventsList.length === 0 && (
         <div className="fixed inset-0 bg-white/80 z-50 flex items-center justify-center">
            <div className="flex flex-col items-center gap-3">
               <Loader2 className="w-8 h-8 animate-spin text-blue-600" />
               <p className="text-sm font-medium text-gray-600">Sedang memuat data...</p>
            </div>
         </div>
      )}

      {/* AI Processing Overlay */}
      {isProcessingAI && (
         <div className="fixed inset-0 bg-white/90 z-[70] flex items-center justify-center">
            <div className="flex flex-col items-center gap-4 animate-pulse">
               <Sparkles className="w-12 h-12 text-purple-600 animate-spin" />
               <div className="text-center">
                  <p className="text-lg font-bold text-gray-800">Sedang Memproses...</p>
                  <p className="text-sm text-gray-500">AI sedang membaca jadual anda dan menyimpannya.</p>
               </div>
            </div>
         </div>
      )}

      {/* MODALS */}
      <AIModal 
        isOpen={isAIModalOpen} 
        onClose={() => setIsAIModalOpen(false)} 
        activeTab={activeTab}
        aiInputText={aiInputText}
        setAiInputText={setAiInputText}
        isProcessingAI={isProcessingAI}
        handleAIProcess={handleAIProcess}
        aiCategory={aiCategory}
        setAiCategory={setAiCategory}
      />

      <BulkSyncModal 
        isOpen={isBulkSyncModalOpen}
        onClose={() => setIsBulkSyncModalOpen(false)}
        logs={syncLogs}
        isSyncing={isSyncing}
        total={syncTotal}
        progress={syncProgress}
      />

      <SyncConfirmationModal 
        isOpen={isSyncConfirmModalOpen}
        onClose={() => setIsSyncConfirmModalOpen(false)}
        onConfirm={runBulkSync}
        count={pendingSyncData?.ids ? pendingSyncData.ids.length : draftEvents.filter(e => pendingSyncData?.category === 'all' || e.category === pendingSyncData?.category).length}
        targetName={pendingSyncData?.category === 'all' ? 'Semua' : (CATEGORY_LABELS[pendingSyncData?.category || ''] || pendingSyncData?.category || '')}
        isSelection={!!pendingSyncData?.ids && pendingSyncData.ids.length > 0}
      />

      <AddEditModal 
        isOpen={isModalOpen} 
        onClose={closeModal} 
        onSubmit={saveEvent}
        formData={formData}
        setFormData={setFormData}
        isSubmitting={isSubmitting}
        editingEvent={editingEvent}
        activeTab={activeTab}
      />

      <DeleteModal 
        isOpen={isDeleteModalOpen} 
        onClose={() => setIsDeleteModalOpen(false)} 
        onConfirm={confirmDelete}
        isSubmitting={isSubmitting}
        activeTab={activeTab}
        count={bulkDeleteIds.length || 1}
      />

      <CopyModal 
        isOpen={isCopyModalOpen} 
        onClose={() => setIsCopyModalOpen(false)} 
        onConfirm={confirmCopy}
        isSubmitting={isSubmitting}
        eventToCopy={eventToCopy}
      />

      <div className="max-w-7xl mx-auto grid grid-cols-1 lg:grid-cols-3 gap-6">

        {/* LEFT COLUMN: Calendar & Navigation */}
        <div className="lg:col-span-2 space-y-6">
          <CalendarSection 
            currentDate={currentDate}
            selectedDate={selectedDate}
            setSelectedDate={setSelectedDate}
            activeTab={activeTab}
            prevMonth={prevMonth}
            nextMonth={nextMonth}
            activeEventsList={activeEventsList}
            terms={SCHOOL_DATA.terms}
            loading={loading}
          />

          <EventListSection 
            events={activeEventsList}
            activeTab={activeTab}
            openEditModal={openEditModal}
            openDeleteModal={openDeleteModal}
            openAddModal={openAddModal}
            openCopyModal={openCopyModal}
            copyingId={eventToCopy?.id}
            openAIModal={openAIModal}
            handleBulkSync={handleBulkSync}
            handleBulkDelete={openBulkDeleteModal}
          />
        </div>

        {/* RIGHT COLUMN: Sidebar (Details & Highlights) */}
        <Sidebar 
          selectedDate={selectedDate}
          currentDate={currentDate}
          selectedEvents={selectedEvents}
          activeEventsList={activeEventsList}
          activeTab={activeTab}
          openAddModal={() => openAddModal()}
          openEditModal={openEditModal}
          openDeleteModal={openDeleteModal}
          openCopyModal={openCopyModal}
          openAIModal={openAIModal}
          copyingId={eventToCopy?.id}
        />

      </div>
      </div>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { Edit, Trash2, Plus, Calendar, Filter, CalendarPlus, Loader2, Sparkles, CloudUpload } from 'lucide-react';
import { SchoolEvent } from '../types';
import { CATEGORY_LABELS, CATEGORY_STYLES } from '../constants';
import { formatEventDateRange, getCategoryIcon } from '../utils';

interface EventListSectionProps {
  events: SchoolEvent[];
  activeTab: 'draft' | 'public';
  openEditModal: (evt: SchoolEvent) => void;
  openDeleteModal: (id: string) => void;
  openAddModal: (category?: string) => void;
  openCopyModal: (evt: SchoolEvent) => void;
  copyingId?: string | null;
  openAIModal: (category?: string) => void;
  handleBulkSync?: (category: string, specificIds?: string[]) => void;
  handleBulkDelete?: (ids: string[]) => void;
}

const TABS = [
  { key: 'all', label: 'Semua' },
  { key: 'holiday', label: 'Cuti' },
  { key: 'academic', label: 'Sekolah' },
  { key: 'exam', label: 'Peperiksaan' },
  { key: 'program', label: 'Program' },
  { key: 'hem', label: 'HEM' },
  { key: 'koko', label: 'Kokurikulum' },
  { key: 'meeting', label: 'Mesyuarat' },
];

export default function EventListSection({
  events,
  activeTab,
  openEditModal,
  openDeleteModal,
  openAddModal,
  openCopyModal,
  copyingId,
  openAIModal,
  handleBulkSync,
  handleBulkDelete
}: EventListSectionProps) {
  const [activeCategory, setActiveCategory] = useState('all');
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  // Filter and Sort Events
  const filteredEvents = events
    .filter(evt => activeCategory === 'all' || evt.category === activeCategory)
    .sort((a, b) => {
        if (!a.start || !b.start) return 0;
        return new Date(a.start).getTime() - new Date(b.start).getTime();
    });

  // Clear selection when events are updated (e.g. after deletion)
  useEffect(() => {
    setSelectedIds(new Set());
  }, [events]);

  const toggleSelection = (id: string) => {
    const newSet = new Set(selectedIds);
    if (newSet.has(id)) newSet.delete(id);
    else newSet.add(id);
    setSelectedIds(newSet);
  };

  const executeBulkDelete = () => {
      if (selectedIds.size === 0 || !handleBulkDelete) return;
      handleBulkDelete(Array.from(selectedIds));
  };

  const executeBulkSync = () => {
      if (!handleBulkSync) return;
      // If selection exists, sync selected IDs. Else, sync entire active category.
      if (selectedIds.size > 0) {
          handleBulkSync(activeCategory, Array.from(selectedIds));
      } else {
          handleBulkSync(activeCategory);
      }
  };

  return (
    <div className="bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden">
      <div className="p-6 border-b border-gray-100 flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
            <h3 className="text-lg font-bold text-gray-800 flex items-center gap-2">
                <Filter size={20} className="text-blue-600" />
                Senarai Pengurusan Takwim
            </h3>
            <p className="text-sm text-gray-500">Urus semua acara sekolah mengikut kategori.</p>
        </div>

        <div className="flex gap-2 items-center flex-wrap sm:flex-nowrap">
            {/* Butang Aksi Pukal */}
            {selectedIds.size > 0 ? (
                <>
                    {handleBulkDelete && (
                        <button 
                            onClick={executeBulkDelete}
                            className="flex items-center gap-2 bg-red-600 hover:bg-red-700 text-white px-3 py-2 sm:px-4 rounded-lg text-sm font-medium transition shadow-sm w-fit animate-in fade-in"
                            title={`Padam ${selectedIds.size} acara yang dipilih`}
                        >
                            <Trash2 size={16} />
                            <span className="hidden sm:inline">Padam ({selectedIds.size})</span>
                        </button>
                    )}
                    {activeTab === 'draft' && handleBulkSync && (
                         <button 
                            onClick={executeBulkSync}
                            className="flex items-center gap-2 bg-emerald-600 hover:bg-emerald-700 text-white px-3 py-2 sm:px-4 rounded-lg text-sm font-medium transition shadow-sm w-fit animate-in fade-in"
                            title={`Sync ${selectedIds.size} acara ke GCal`}
                        >
                            <CloudUpload size={16} />
                            <span className="hidden sm:inline">Sync ({selectedIds.size})</span>
                        </button>
                    )}
                </>
            ) : (
                <>
                     {/* Butang Default (Tiada Pilihan) */}
                    {activeTab === 'draft' && handleBulkSync && (
                        <button 
                            onClick={executeBulkSync}
                            className="flex items-center gap-2 bg-emerald-600 hover:bg-emerald-700 text-white px-3 py-2 sm:px-4 rounded-lg text-sm font-medium transition shadow-sm w-fit"
                            title="Sync GCal (Kategori Ini)"
                        >
                            <CloudUpload size={16} />
                            <span className="hidden sm:inline">Sync GCal</span>
                        </button>
                    )}
                </>
            )}

            <button 
                onClick={() => openAIModal(activeCategory)}
                className="flex items-center gap-2 bg-purple-600 hover:bg-purple-700 text-white px-3 py-2 sm:px-4 rounded-lg text-sm font-medium transition shadow-sm w-fit"
                title="AI Import"
            >
                <Sparkles size={16} />
                <span className="hidden sm:inline">AI Import</span>
            </button>
            <button 
                onClick={() => openAddModal(activeCategory === 'all' ? 'program' : activeCategory)}
                className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-3 py-2 sm:px-4 rounded-lg text-sm font-medium transition shadow-sm w-fit"
                title="Tambah Event"
            >
                <Plus size={16} />
                <span className="hidden sm:inline">Tambah Event</span>
            </button>
        </div>
      </div>

      {/* Tabs */}
      <div className="border-b border-gray-100 overflow-x-auto">
        <div className="flex px-4 min-w-max">
            {TABS.map((tab) => (
                <button
                    key={tab.key}
                    onClick={() => {
                        setActiveCategory(tab.key);
                        setSelectedIds(new Set()); // Reset selection on tab change
                    }}
                    className={`px-4 py-3 text-sm font-medium border-b-2 transition-colors duration-200 ${
                        activeCategory === tab.key 
                        ? 'border-blue-600 text-blue-600' 
                        : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                    }`}
                >
                    {tab.label}
                </button>
            ))}
        </div>
      </div>

      {/* Event List */}
      <div className="bg-gray-50 min-h-[300px] max-h-[600px] overflow-y-auto p-4 custom-scrollbar">
        {filteredEvents.length > 0 ? (
            <div className="space-y-3">
                {filteredEvents.map((evt, idx) => (
                    <div 
                        key={evt.id || idx} 
                        className={`bg-white p-4 rounded-xl shadow-sm border flex flex-col sm:flex-row gap-4 items-start sm:items-center hover:shadow-md transition-shadow group
                         ${evt.id && selectedIds.has(evt.id) ? 'border-blue-300 ring-1 ring-blue-300 bg-blue-50' : 'border-gray-100'}`}
                    >
                        {/* Checkbox Selection */}
                        <div className="flex items-center justify-center pl-1 sm:pl-2">
                            <input 
                                type="checkbox"
                                checked={evt.id ? selectedIds.has(evt.id) : false}
                                onChange={() => evt.id && toggleSelection(evt.id)}
                                className="w-5 h-5 text-blue-600 border-gray-300 rounded focus:ring-blue-500 cursor-pointer accent-blue-600"
                            />
                        </div>

                        {/* Date Box */}
                        <div className="flex sm:flex-col items-center justify-center bg-gray-100 rounded-lg p-2 min-w-[4rem] sm:min-w-[5rem] text-center shrink-0 gap-2 sm:gap-0">
                             <span className="text-xs font-bold text-gray-500 uppercase">
                                {evt.start ? new Date(evt.start).toLocaleString('ms-MY', { month: 'short' }) : '-'}
                             </span>
                             <span className="text-xl sm:text-2xl font-bold text-gray-800 leading-none">
                                {evt.start ? new Date(evt.start).getDate() : '-'}
                             </span>
                        </div>

                        {/* Content */}
                        <div className="flex-1 min-w-0">
                            <div className="flex items-center gap-2 mb-1">
                                <span className={`text-[10px] px-2 py-0.5 rounded-full font-medium border ${CATEGORY_STYLES[evt.category]?.replace('bg-', 'bg-opacity-20 ')}`}>
                                    {CATEGORY_LABELS[evt.category]}
                                </span>
                            </div>
                            <h4 className="font-semibold text-gray-800 text-sm sm:text-base mb-1">{evt.title}</h4>
                            <div className="flex items-center gap-4 text-xs text-gray-500">
                                <span className="flex items-center gap-1">
                                    <Calendar size={12} />
                                    {formatEventDateRange(evt)}
                                </span>
                            </div>
                        </div>

                        {/* Actions */}
                        <div className="flex items-center gap-2 w-full sm:w-auto justify-end border-t sm:border-t-0 pt-3 sm:pt-0 mt-2 sm:mt-0 border-gray-100">
                            {/* Butang Tambah ke Takwim Rasmi (Hanya untuk Draf) */}
                            {activeTab === 'draft' && (
                                <button 
                                    onClick={() => openCopyModal(evt)}
                                    className="p-2 text-emerald-600 bg-emerald-50 hover:bg-emerald-100 rounded-lg transition border border-emerald-100"
                                    title="Tambah ke Takwim Rasmi"
                                    disabled={copyingId === evt.id}
                                >
                                    {copyingId === evt.id ? <Loader2 size={16} className="animate-spin" /> : <CalendarPlus size={16} />}
                                </button>
                            )}

                            <button 
                                onClick={() => openEditModal(evt)}
                                className="p-2 text-blue-600 bg-blue-50 hover:bg-blue-100 rounded-lg transition"
                                title="Edit"
                            >
                                <Edit size={16} />
                            </button>
                            <button 
                                onClick={() => evt.id && openDeleteModal(evt.id)}
                                className="p-2 text-red-600 bg-red-50 hover:bg-red-100 rounded-lg transition"
                                title="Padam"
                            >
                                <Trash2 size={16} />
                            </button>
                        </div>
                    </div>
                ))}
            </div>
        ) : (
            <div className="flex flex-col items-center justify-center h-64 text-gray-400">
                <Calendar size={48} className="mb-4 opacity-20" />
